(window.GIM_TS=window.GIM_TS||{})["Bava Batra.3"]={"from":72,"a":[["\u0003מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 \u0003רבא,\u0004 מדוע קונה בעל האילן קרקע תחת האילן שלו? \u0003ולימא ליה\u0004 \u0005[ושיאמר לו]\u0006 בעל הקרקע: \u0003כורכמא דרישקא זביני\u0004 \u0005[כרכום הגינה מכרתי]\u0006 \u0003לך, עקור כורכמא דרישקא וזיל\u0004 \u0005[\u0006את \u0005כרכום הגינה ולך],\u0006 שלא מכרתי לך אלא זכות שימוש בקרקע לגידול הדקל, ולא את גופה של הקרקע! \u0003אלא אמר רבא:\u0004 כאן מדובר \u0003בבא מחמת טענה,\u0004 שהקונה טוען שהוסכם עם המוכר שהוא קונה את האילן והקרקע שתחתיו.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003מר קשישא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב חסדא לרב אשי: ואי כורכמא דרישקא זבין ליה, מאי הוה ליה למעבד\u0004 \u0005[ואם\u0006 באמת \u0005כרכום גינה\u0006 לגידול \u0005מכר לו, מה היה לו לעשות]\u0006 כדי שלא יחזיק בקרקע לאחר שלוש שנים ויטען שקנה ממנו במפורש גם את הקרקע? ומשיבים: \u0003איבעי ליה למחויי\u0004 \u0005[היה צריך למחות]\u0006 בתוך שלוש השנים.","\u0003דאי\u0004 \u0005[שאם]\u0006 \u0003לא תימא הכי\u0004 \u0005[תאמר כך],\u0006 שסומכים על מחאה כזו, \u0003הני\u0004 \u0005[אותם]\u0006 שטרות של \u0003משכנתא\u0004 של \u0003סורא\u0004 שהמלוה גובה את חובו על ידי שהוא מחזיק בקרקעו של הלווה ואוכל מפירותיה במשך זמן מסויים בהתאם לגודל החוב, \u0003דכתב\u0004 \u0005[שכתוב]\u0006 \u0003בה\u0004 במשכנתא \u0003הכי\u0004 \u0005[כך]:\u0006 \u0003\"במישלם שניא אלין תיפוק ארעא דא\u0004 \u0005[בסוף השנים האלה תצא קרקע זו]\u0006 \u0003בלא כסף\u0004 ותחזור לבעליה \u0003\",\u0004 \u0003אי כביש ליה\u0004 \u0005[אם יחביא אותו]\u0006 המלוה את \u0003שטר\u0004 ה\u0003משכנתא,\u0004 \u0003ואמר\u0004 \u0005[ויאמר]\u0006 לאחר שלוש שנים \u0003\"לקוחה היא בידי\", הכי נמי דמהימן\u0004 \u0005[כך גם כן\u0006 תאמר \u0005ש\u0006הוא \u0005נאמן]?\u0006 ודאי אין לומר כן, כי הסדר זה של פירעון משכנתא תיקנו חכמים, וכי \u0003מיתקני רבנן מילתא דאתי\u0004 \u0005[מתקנים חכמים דבר שבא]\u0006 \u0003בה לידי פסידא\u0004 \u0005[הפסד]?\u0006 \u0003אלא\u0004 ההנחה היא כי \u0003איבעי ליה למחויי\u0004 \u0005[צריך הוא למחות]\u0006 לפני תום שלוש שנים ולהודיע שקרקע זו שלו היא, ואם לא — מפסיד הוא לעצמו את הקרקע. \u0003הכא נמי איבעי ליה למחויי\u0004 \u0005[כאן גם כן היה צריך למחות]\u0006 ולהודיע שקרקע זו שלו היא.","\u0003שלש ארצות לחזקה\u0004 בתוך ארץ ישראל, והן: \u0003יהודה, ועבר הירדן, והגליל.\u0004 ומה עניינה של חלוקה זו? אם \u0003היה\u0004 בעל הקרקע \u0003ביהודה והחזיק\u0004 אדם בקרקעו \u0003בגליל,\u0004 או היה \u0003בגליל והחזיק ביהודה\u0004 — \u0003אינה חזקה,\u0004 אף אם לא מחה במשך שלוש שנים, \u0003עד שיהא\u0004 בעל הקרקע \u0003עמו במדינה אחת. אמר ר' יהודה: לא אמרו שלש שנים\u0004 של חזקה, \u0003אלא כדי שיהא\u0004 בעל הקרקע \u0003באספמיא\u0004 הרחוקה \u0003ויחזיק\u0004 אדם בקרקע שלו \u0003שנה, ילכו\u0004 \u0003ויודיעוהו שנה,\u0004 שעד שיגיעו אנשים אל בעל הקרקע באספמיא תעבור עוד שנה, \u0003ויבא\u0004 בעל הקרקע \u0003לשנה אחרת\u0004 לדון עם המחזיק.","ושואלים: \u0003מאי קסבר\u0004 \u0005[מה סבור]\u0006 ה\u0003תנא קמא\u0004 \u0005[הראשון],\u0006 מה היא שיטתו העקרונית? \u0003אי קסבר\u0004 \u0005[אם הוא סבור]\u0006 ש\u0003מחאה\u0004 שמוחה הבעלים \u0003שלא בפניו\u0004 של המחזיק \u0003הויא\u0004 \u0005[הריהי\u0006 נחשבת\u0005]\u0006 \u0003מחאה, אפילו\u0004 אם היה ב\u0003יהודה וגליל נמי\u0004 \u0005[גם כן]\u0006 תהא זו מחאה, ואם לא מחה — תהא חזקה למחזיק! \u0003אי קסבר\u0004 \u0005[אם הוא סבור]\u0006 ש\u0003מחאה שלא בפניו לא הויא\u0004 \u0005[אינה]\u0006 \u0003מחאה, אפילו\u0004 במקומות שונים בתוך \u0003יהודה ויהודה\u0004 \u0003נמי\u0004 \u0005[גם כן]\u0006 \u0003לא\u0004 תועיל המחאה,","שצריך למחות בפניו ממש! \u0003אמר ר' אבא בר ממל אמר רב, לעולם\u0004 תפרש כי \u0003קסבר\u0004 \u0005[הוא סבור]:\u0006 \u0003מחאה שלא בפניו הויא\u0004 \u0005[הריהי]\u0006 \u0003מחאה, ומשנתינו\u0004 לפיה מחאה בגליל אינה נחשבת ליהודה — \u0003בשעת חירום\u0004 (מלחמה) \u0003שנו,\u0004 שאין לסמוך על כך שהשמועות עוברות ממקום למקום, ואין המחזיק יכול לטעון שצריך היה הבעלים למחות, ומשלא מחה — שדה זו שלו היא. ושואלים: \u0003ומאי שנא\u0004 \u0005[ומה שונה]\u0006 \u0003יהודה וגליל דנקיט\u0004 \u0005[שתפס]?\u0006 שהרי היה צריך לומר סתם שתי מדינות שהן בשעת חירום?","ומשיבים: \u0003הא קא משמע לן\u0004 \u0005[\u0006דבר \u0005זה משמיע לנו\u0006 בכך\u0005],\u0006"],["ש\u0003סתם יהודה וגליל כשעת חירום דמו\u0004 \u0005[נחשבים].\u0006 כלומר, בדרך כלל המעבר ביניהם קשה, ואין לסמוך על מחאה שנאמרה במקום אחד לגבי חזקה הנעשית בשני.","\u0003אמר רב יהודה אמר רב: אין מחזיקין בנכסי בורח,\u0004 שכיון שהוא בורח אינו יכול לבוא ולמחות. \u0003כי אמריתה קמיה\u0004 \u0005[כאשר אמרתי את\u0006 הדבר \u0005לפני]\u0006 \u0003שמואל, אמר לי: וכי למחות בפניו הוא צריך?\u0004 אלא ימחה במקומו!","ושואלים: \u0003ורב, מאי קא משמע לן\u0004 \u0005[מה השמיע לנו\u0006 בכך\u0005]?\u0006 ש\u0003מחאה שלא בפניו לא הויא\u0004 \u0005[אינה]\u0006 \u0003מחאה? והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003רב\u0004 לעיל להיפך: \u0003מחאה שלא בפניו הויא\u0004 \u0005[הריהי]\u0006 \u0003מחאה!\u0004 ומשיבים: \u0003רב טעמא\u0004 \u0005[\u0006את \u0005הטעם]\u0006 של ה\u0003תנא דידן קמפרש\u0004 \u0005[שלנו הוא מפרש]\u0006 \u0003וליה לא סבירא ליה\u0004 \u0005[ו\u0006אולם \u0005הוא עצמו אינו סבור כן],\u0006 ולדעתו מחאה שלא בפניו מחאה היא.","\u0003ואיכא דאמרי\u0004 \u0005[ויש שאומרים]\u0006 בלשון אחרת, \u0003אמר רב יהודה אמר רב: מחזיקים בנכסי בורח. כי אמריתה קמיה\u0004 \u0005[כאשר אמרתי\u0006 שמועה זו \u0005לפני]\u0006 \u0003שמואל, אמר לי:\u0004 \u0003פשיטא\u0004 \u0005[פשוט\u0006 הוא\u0005],\u0006 \u0003וכי למחות בפניו הוא צריך?\u0004","ושואלים: \u0003ורב, מאי קא משמע לן\u0004 \u0005[מה השמיע לנו\u0006 בכך\u0005]?\u0006 ש\u0003מחאה שלא בפניו הויא\u0004 \u0005[הריהי]\u0006 \u0003מחאה? והא\u0004 \u0005[והרי]\u0006 \u0003אמרה\u0004 \u0003רב חדא זימנא\u0004 \u0005[פעם אחת]!\u0006 \u0003אלא הא קא משמע לן\u0004 \u0005[\u0006דבר \u0005זה השמיע לנו],\u0006 ש\u0003אפילו מיחה בפני שנים שאין יכולין לומר לו\u0004 למחזיק — מכל מקום \u0003הויא\u0004 \u0005[הריהי]\u0006 \u0003מחאה;\u0004 ש","\u0003אמר רב ענן: לדידי מפרשא לי מיניה דמר\u0004 \u0005[לי נתפרש\u0006 הדבר \u0005ממנו ממר]\u0006 \u0003שמואל\u0004 עצמו: \u0003מיחה בפני שני בני אדם שיכולים לומר לו\u0004 למחזיק — \u0003הויא\u0004 \u0005[הריהי]\u0006 \u0003מחאה, מיחה בפני שני בני אדם שאין יכולין לומר לו\u0004 — \u0003לא הויא\u0004 \u0005[אינה]\u0006 \u0003מחאה. ו\u0004אילו \u0003רב\u0004 סבור: \u0003חברך חברא אית ליה, וחברא דחברך חברא אית ליה\u0004 \u0005[חברך חבר יש לו, וחבר של חברך חבר יש לו],\u0006 ובסופו של דבר תגיע השמועה למי שצריך לדעת עליה.","\u0003אמר רבא, הלכתא\u0004 \u0005[הלכה\u0006 היא\u0005]:\u0006 \u0003אין מחזיקין בנכסי בורח, ומחאה שלא בפניו הויא\u0004 \u0005[הריהי]\u0006 \u0003מחאה.\u0004 ושואלים: \u0003תרתי\u0004 \u0005[שנים]?!\u0006 כיצד אמר שני דברים הסותרים זה את זה? והרי יכול הבורח למחות במקום אחר, שלא בפני המחזיק! ומשיבים: \u0003לא קשיא\u0004 \u0005[אין\u0006 זה \u0005קשה]:\u0006 \u0003כאן\u0004 מדובר ב\u0003בורח מחמת ממון,\u0004 שכיון שבורח רק מחמת ממון יכול הוא לחזור ולמחות באופן כלשהו, או לדאוג שהמחאה תגיע, \u0003כאן\u0004 מדובר ב\u0003בורח מחמת מרדין\u0004 (רצח) שחשדוהו ברצח. ובמקרה זה אינו יכול לחזור למקום, ואף אינו יכול להפיץ שמועה, שמא על ידי כך יוודע היכן הוא נמצא.","\u0003היכי דמי\u0004 \u0005[כיצד היא בדיוק]\u0006 \u0003מחאה? אמר רב זביד:\u0004 אם הבעלים אומר \u0003\"פלניא גזלנא\u0004 \u0005[פלוני גזלן]\u0006 \u0003הוא\"\u0004 — \u0003לא הויא\u0004 \u0005[אין זו]\u0006 \u0003מחאה,\u0004 שהרי לא פירש באיזה ענין הוא מאשימו, ואין המחזיק יודע להיזהר בשטרו. אבל אם אמר \u0003\"פלניא גזלנא\u0004 \u0005[פלוני גזלן]\u0006 \u0003הוא, דנקיט לה לארעאי בגזלנותא\u0004 \u0005[שמחזיק את קרקעי בגזלנות],\u0006"],["\u0003ולמחר,\u0004 כלומר, בעתיד \u0003תבענא ליה בדינא\"\u0004 \u0005[אתבע אותו לדין]\u0006 — \u0003הויא\u0004 \u0005[הריהו]\u0006 \u0003מחאה.\u0004","ושואלים: \u0003אמר\u0004 הבעלים כל מה שצריך לומר במחאה כשמוחה, אבל הוסיף ואמר לשומעים: \u0003לא תימרו ליה\u0004 \u0005[אל תאמרו לו]\u0006 למחזיק שמחיתי בו, \u0003מאי\u0004 \u0005[מה]\u0006 הדין? \u0003אמר רב זביד: הא קאמר\u0004 \u0005[הרי הוא אומר]\u0006 \u0003\"לא תימרו ליה\u0004 \u0005[תאמרו לו]\u0006 \u0003\",\u0004 ואין המחזיק יודע על המחאה, ובטלה המחאה. \u0003רב פפא אמר:\u0004 כוונתו היא, \u0003לדידיה לא תימרו ליה\u0004 \u0005[לו עצמו אל תאמרו],\u0006 \u0003לאחריני אימרו להו\u0004 \u0005[לאחרים אמרו להם].\u0006 ובסופו של דבר יוודע הדבר גם לו, שהרי \u0003חברך חברא אית ליה, חברא דחברך חברא אית ליה\u0004 \u0005[חברך חבר יש לו, חבר של חברך חבר יש לו].\u0006","ועוד מקרה, \u0003אמרו ליה\u0004 \u0005[לו]\u0006 השומעים את המחאה: \u0003לא אמרינן ליה\u0004 \u0005[אין אנו אומרים לו]\u0006 למחזיק את מחאתך, האם צריך למחות בפני אחרים? \u0003אמר רב זביד: הא קא אמרו ליה \"לא אמרינן ליה\"\u0004 \u0005[הרי אמרו לו \"אין אנו אומרים לו\"]\u0006 וכאילו לא מחה. \u0003רב פפא אמר:\u0004 כוונתם היתה \u0003לדידיה לא אמרינן ליה, לאחריני אמרי להו\u0004 \u0005[לו עצמו אין אנו אומרים לו, לאחרים נאמר להם],\u0006 \u0003חברך חברא אית ליה, וחברא דחברך חברא אית ליה\u0004 \u0005[חברך חבר יש לו, וחבר של חברך חבר יש לו],\u0006 ובסוף יוודע הדבר.","ועוד, \u0003אמר\u0004 הבעלים המוחה \u0003להו\u0004 \u0005[להם\u0006 לשומעים\u0005]:\u0006 \u0003לא תיפוק לכו שותא\u0004 \u0005[תצא לכם\u0006 מפיכם \u0005אמירה]\u0006 בענין זה. כלומר, איני רוצה שיוודע הדבר כלל. \u0003אמר רב זביד: הא קאמר\u0004 \u0005[הרי הוא\u0006 \u0005אומר]\u0006 \u0003\"לא תיפוק לכו שותא\u0004 \u0005[תצא לכם\u0006 מפיכם \u0005אמירה]\u0006 \u0003\",\u0004 ובמקרה זה גם רב פפא מודה. ועוד, \u0003אמרו ליה\u0004 \u0005[לו]:\u0006 \u0003לא מפקינן שותא\u0004 \u0005[אין אנו מוציאים אמירה\u0006 מפינו\u0005]\u0006 בענין זה. \u0003אמר רב פפא: הא קאמרי ליה\u0004 \u0005[הרי אמרו לו]\u0006 \u0003\"לא מפקינן שותא\u0004 \u0005[אין אנו מוציאים אמירה]\u0006 \u0003\".\u0004 \u0003רב הונא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב יהושע אמר: כל מילתא דלא רמיא עליה דאיניש\u0004 \u0005[דבר שאינו מוטל עליו על אדם]\u0006 לשמור בסוד מטעמיו שלו, \u0003אמר לה ולאו אדעתיה\u0004 \u0005[אומר אותו בלא דעתו],\u0006 ששוכח את הבטחתו, ובסופו של דבר יוודע הדבר, למרות שהעדים אמרו שלא יספרו.","\u0003אמר רבא אמר רב נחמן: מחאה שלא בפניו\u0004 \u0003הויא\u0004 \u0005[הריהי]\u0006 \u0003מחאה. איתיביה\u0004 \u0005[הקשה לו]\u0006 \u0003רבא לרב נחמן:\u0004 שנינו, \u0003אמר ר' יהודה: לא אמרו שלש שנים, אלא כדי שיהא\u0004 בעל הקרקע \u0003באספמיא ויחזיק\u0004 המחזיק בה \u0003שנה, וילכו ויודיעוהו שנה, ויבא לשנה אחרת. ואי סלקא דעתך\u0004 \u0005[ואם עולה על דעתך]\u0006 לומר ש\u0003מחאה שלא בפניו הויא\u0004 \u0005[הריהי]\u0006 \u0003מחאה, למה לי למיתי\u0004 \u0005[למה לו לבוא]?\u0006 \u0003ליתיב התם אדוכתיה ולימחי\u0004 \u0005[שישב שם במקומו ושימחה]!\u0006 ומשיבים: \u0003התם\u0004 \u0005[שם]\u0006 \u0003עצה טובה קא משמע לן\u0004 \u0005[השמיע לנו],\u0006 \u0003דניתי ונשקול ארעא ופירי\u0004 \u0005[שיבוא ויקח\u0006 את \u0005הקרקע ו\u0006את \u0005הפירות\u0006 שלו\u0005],\u0006 שאם הוא עצמו לא יבוא, בסוף לא יוכל להוציא את הפירות מן המחזיק.","ומעירים: \u0003מדקא מותיב ליה\u0004 \u0005[מ\u0006מה \u0005שמקשה לו]\u0006 \u0003רבא לרב נחמן\u0004 בענין זה, \u0003מכלל\u0004 הדברים אתה למד \u0003דלא סבירא ליה\u0004 \u0005[שאין הוא סבור]\u0006 ש\u0003מחאה שלא בפניו הויא\u0004 \u0005[הריהי]\u0006 \u0003מחאה, והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003רבא\u0004 עצמו: \u0003מחאה שלא בפניו הויא\u0004 \u0005[הריהי]\u0006 \u0003מחאה!\u0004 ומשיבים: אין זה קושי, \u0003בתר\u0004 \u0005[אחרי]\u0006 ש\u0003שמעה\u0004 את ההלכה הזו \u0003מרב נחמן\u0004 \u0005גם\u0006 הוא \u0003סברה\u0004 (קיבל אותה).","מסופר, \u0003אשכחינהו\u0004 \u0005[מצא אותם]\u0006 \u0003ר' יוסי בר' חנינא לתלמידיו\u0004 של \u0003ר' יוחנן, אמר להו\u0004 \u0005[להם]:\u0006 \u0003מי\u0004 \u0005[האם]\u0006 \u0003אמר ר' יוחנן מחאה בכמה?\u0004 בפני כמה אנשים צריך בעל הנכס לומר אותה כדי שתיחשב למחאה? \u0003ר' חייא בר אבא אמר\u0004 בשם \u0003ר' יוחנן: מחאה בפני שנים. ר' אבהו אמר\u0004 בשם \u0003ר' יוחנן: מחאה בפני שלשה.\u0004","ומציעים: \u0003לימא\u0004 \u0005[האם לומר]\u0006 שבדברי \u0003רבה בר רב הונא קא מיפלגי\u0004 \u0005[חלוקים הם],\u0006 ש\u0003אמר רבה בר רב הונא: כל מילתא דמתאמרא באפי תלתא\u0004 \u0005[דבר שנאמר\u0006 \u0005בפני שלושה]\u0006"],["\u0003לית\u0004 \u0005[אין]\u0006 \u0003בה משום לישנא בישא\u0004 \u0005[לשון הרע],\u0006 שאם דבר נאמר כבר בפני שלושה, הריהו נודע ומתפרסם ברבים. \u0003מאן דאמר\u0004 \u0005[מי שאומר]\u0006 \u0003בפני שנים\u0004 — \u0003לית ליה\u0004 \u0005[אין לו],\u0006 אינו מקבל את דברי \u0003רבה בר רב הונא,\u0004 שסבור שגם בפני שנים נודע הדבר לכל, \u0003ומאן דאמר\u0004 \u0005[ומי שאומר]\u0006 \u0003בפני שלשה\u0004 — \u0003אית ליה\u0004 \u0005[יש לו,\u0006 מקבל\u0005]\u0006 את דברי \u0003רבה בר רב הונא?\u0004","ודוחים: \u0003לא, דכולי עלמא אית להו\u0004 \u0005[לדעת הכל יש להם,\u0006 מקבלים\u0005]\u0006 את דברי \u0003רבה בר רב הונא, והכא בהא קא מיפלגי\u0004 \u0005[וכאן ב\u0006ענין \u0005זה הם חלוקים]:\u0006 \u0003מאן דאמר\u0004 \u0005[מי שאומר]\u0006 \u0003בפני שנים, קסבר\u0004 \u0005[הוא סבור]:\u0006 \u0003מחאה שלא בפניו לא הויא\u0004 \u0005[אין היא]\u0006 \u0003מחאה\u0004 וצריך למחות בפניו דווקא, ואם יש לו שני עדים שמחה בפניו, די בכך כדי להוכיח את הדבר. \u0003ומאן דאמר\u0004 \u0005[ומי שאומר]\u0006 \u0003בפני שלשה, קסבר\u0004 \u0005[הוא סבור]:\u0006 \u0003מחאה שלא בפניו הויא\u0004 \u0005[הריהי]\u0006 \u0003מחאה,\u0004 ולכן צריך לעשות אותה בשלושה, כדי שיתפרסם הדבר.","\u0003אי בעית אימא\u0004 \u0005[אם תרצה אמור]\u0006 באופן אחר: \u0003דכולי עלמא\u0004 \u0005[לדעת הכל]\u0006 \u0003מחאה שלא בפניו הויא\u0004 \u0005[הריהי]\u0006 \u0003מחאה, והכא בהא קמיפלגי\u0004 \u0005[וכאן בזה הם חלוקים]:\u0006 \u0003מאן דאמר\u0004 \u0005[מי שאומר]\u0006 \u0003בפני שנים, סבר\u0004 \u0005[סבור]:\u0006 \u0003סהדותא בעינן\u0004 \u0005[עדות אנו צריכים]\u0006 והרי שנים הם עדים, והמחאה כבר תגיע לאוזני המחזיק. \u0003ומאן דאמר\u0004 \u0005[ומי שאומר]\u0006 \u0003בפני שלשה, קסבר\u0004 \u0005[סבר]:\u0006 \u0003גלויי מילתא בעינן\u0004 \u0005[גילוי דברים\u0006 ופרסום \u0005אנו צריכים]\u0006 ודבר זה אינו אלא בשלושה.","ובצד אחר של דין חזקה מסופר: \u0003גידל בר מניומי הוה ליה מחויאתה למחויי\u0004 \u0005[היתה לו מחאה למחות]\u0006 על מישהו שהחזיק בקרקעו. \u0003אשכחינהו\u0004 \u0005[מצא אותם]\u0006 \u0003לרב הונא ולחייא בר רב ולרב חלקיה בר טובי דהוו יתבי\u0004 \u0005[שהיו יושבים],\u0006 \u0003ומחה קמייהו\u0004 \u0005[בפניהם]\u0006 שמישהו מחזיק בקרקעו שלא כדין. \u0003לשנה\u0004 הבאה \u0003הדר אתא למחויי\u0004 \u0005[חזר\u0006 ו\u0005בא למחות\u0006 עוד פעם\u0005],\u0006 \u0003אמרו ליה\u0004 \u0005[לו]:\u0006 \u0003לא צריכת\u0004 \u0005[אין אתה צריך\u0006 לכך\u0005],\u0006 כי \u0003הכי\u0004 \u0005[כך]\u0006 \u0003אמר רב: כיון שמיחה שנה ראשונה, שוב אינו צריך למחות. ואיכא דאמרי\u0004 \u0005[ויש שאומרים]\u0006 בלשון אחרת, ש\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003חייא בר רב: כיון שמיחה שנה ראשונה, שוב אין צריך למחות.\u0004","ובענין זה \u0003אמר ריש לקיש משום בר קפרא: וצריך למחות בסוף כל שלש ושלש\u0004 שנים, כדי שלא יהיו שלוש שנים רצופות ללא מחאה. \u0003תהי בה\u0004 \u0005[תהה בכך]\u0006 \u0003ר' יוחנן, וכי גזלן יש לו חזקה\u0004 עד שצריכים בכל שלוש שנים להרע את חזקתו? הרי מאחר שמחה המערער והודיע שקרקע זו אינה של המחזיק, מדוע תועיל ישיבתו בקרקע להוכיח את בעלותו? ותוהים על הלשון: \u0003גזלן סלקא דעתך\u0004 \u0005[עולה על דעתך]?\u0006 הרי לא ברור לנו שגזלן הוא, ואין כאן אלא מחאה, שמאשים אותו הלה בגזלנות, ולא יותר! \u0003אלא,\u0004 כך תמה ר' יוחנן: מי שהוא \u0003כגזלן\u0004 שמחו בו הבעלים \u0003יש לו חזקה?\u0004","\u0003אמר רבא, הלכתא\u0004 \u0005[הלכה\u0006 היא\u0005]:\u0006 בכל זאת \u0003צריך למחות בסוף כל שלש ושלש.\u0004 ועוד בענייני מחאה \u0003תני\u0004 \u0005[שנה]\u0006 \u0003בר קפרא: ערער, חזר וערער, חזר וערער\u0004 על החזקה של קרקע, \u0003אם מחמת טענה ראשונה ערער\u0004 שחזר וטען אותה טענה — \u0003אין לו\u0004 למחזיק \u0003חזקה, ואם לאו\u0004 שטען המערער בכל פעם טענות חדשות — \u0003יש לו חזקה,\u0004 שכיון ששינה המערער את טענתו — הערעור הקודם בטל לגמרי, ונמצא שיש לו למחזיק חזקה בקרקע.","\u0003אמר רבא אמר רב נחמן: מחאה\u0004 עושים \u0003בפני שנים,\u0004"],["\u0003ואין צריך לומר\u0004 להם: \u0003\"כתובו\",\u0004 אלא הם עצמם יכולים מיד לכתוב תעודה שבה הם מעידים שפלוני מחה בפניהם. וכן \u0003מודעא\u0004 שמודיע שפעולה משפטית מסויימת שעומד לעשות, כגון מכירה, הוא מעשה שנעשה מפני אונס, שלא ברצונו, אף היא צריכה להיעשות \u0003בפני שנים, ואין צריך לומר: \"כתובו\",\u0004 אלא כותבים מעצמם.","\u0003הודאה\u0004 שמודה שהוא חייב ממון לאחר, צריך לעשות \u0003בפני שנים, ו\u0004אולם במקרה זה \u0003צריך לומר\u0004 להם: \u0003\"כתובו\".\u0004 ואם לא ציוה שיכתבו — אין להם לכתוב שטר שמכניסו להתחייבויות שאינו חפץ בהן. \u0003קנין\u0004 סודר שעושים כדי לגמור עיסקה, עושים \u0003בפני שנים, ואינו צריך לומר:\u0004 \u0003\"כתובו\". קיום שטרות\u0004 שבית דין מאשרים את כשרותו של שטר, וכותבים זאת על השטר — \u0003בשלשה\u0004","\u0003(סימן\u0004 להלכות אלו: \u0003ממה\"ק\u0004 — \u0003מ\u0004חאה, \u0003מ\u0004ודעה, \u0003ה\u0004ודאה, \u0003ק\u0004נין).","\u0003אמר רבא: אי קשיא\u0004 \u0005[אם קשה]\u0006 \u0003לי\u0004 ביחס להלכות האלה שאמר רב נחמן, \u0003הא קשיא\u0004 \u0005[זה קשה]\u0006 \u0003לי: האי קנין היכי דמי\u0004 \u0005[קנין זה\u0006 שהזכרנו \u0005איך הוא בדיוק]\u0006 בתורת מה הוא נחשב? \u0003אי\u0004 \u0005[אם]\u0006 \u0003כמעשה בית דין דמי\u0004 \u0005[\u0006הוא \u0005נחשב],\u0006 אם כן \u0003ליבעי תלתא\u0004 \u0005[שיצטרך שלושה]\u0006 אנשים שייעשה בפניהם, שאין בית דין פחות משלושה! \u0003אי\u0004 \u0005[אם]\u0006 \u0003לא כמעשה בית דין דמי\u0004 \u0005[\u0006הוא \u0005נחשב],\u0006 אלא כעדות בלבד, \u0003אמאי\u0004 \u0005[מדוע]\u0006 \u0003אינו צריך לומר\u0004 במפורש: \u0003\"כתובו\"?\u0004 והרי זה כמו הודאה, שמחייב את עצמו בדבר, שאין העדים רשאים לכותבה ללא הוראה מפורשת!","\u0003בתר דבעי הדר פשטא\u0004 \u0005[אחר ששאל\u0006 את השאלה \u0005חזר\u0006 ו\u0005פתר אותה]:\u0006 \u0003לעולם לאו\u0004 \u0005[לא]\u0006 \u0003כמעשה בית דין דמי\u0004 \u0005[נחשב],\u0006 \u0003והכא טעמא מאי\u0004 \u0005[וכאן מהו הטעם]\u0006 ש\u0003אינו צריך לומר: \"כתובו\"\u0004 כדי שיוכלו לכתוב? \u0003משום\u0004 ש\u0003סתם קנין לכתיבה עומד,\u0004 שעשיית הקנין עצמה מורה שהוא רוצה שייעשה הדבר בכל מיני חיזוק.","\u0003רבה ורב יוסף דאמרי תרוייהו\u0004 \u0005[שאמרו שניהם]:\u0006 \u0003לא כתבינן\u0004 \u0005[אין אנו כותבים]\u0006 \u0003מודעה\u0004 כאשר בא אדם ומודיע שהוא עומד לעשות דבר מחמת שאונס אותו אדם מסויים לכך, \u0003אלא\u0004 \u0003אמאן\u0004 \u0005[על מי]\u0006 ש\u0003לא ציית דינא\u0004 \u0005[מציית לדין],\u0006 כי אז אי אפשר לומר לבעל המודעה: מדוע מסכים אתה לעשות עסקה שלא מרצונך ואינך תובע אותו לדין? ואילו \u0003אביי ורבא דאמרי תרוייהו\u0004 \u0005[שאמרו שניהם]:\u0006 \u0003אפילו עלי ועליך\u0004 אפשר לעשות מודעה, שפעמים אין אפשרות לפתור את הדבר באמצעות בית הדין. \u0003אמרי נהרדעי\u0004 \u0005[אמרו\u0006 חכמי \u0005נהרדעא]:\u0006 \u0003כל מודעא\u0004"],["\u0003לא כתיב\u0004 \u0005[כתוב]\u0006 \u0003בה\u0004 נוסח זה: \u0003\"אנן ידעינן ביה באונסא דפלניא\u0004 \u0005[אנו\u0006 העדים \u0005יודעים בו באונס של פלוני]\u0006 שמשום אונס זה הוא נאלץ לחתום ולהסכים לעיסקה שאינו רוצה בה \u0003\"\u0004— \u0003לאו\u0004 \u0005[לא]\u0006 \u0003מודעא היא.\u0004","ושואלים: \u0003מודעא דמאי\u0004 \u0005[של מה],\u0006 על מה מוסר הוא מודעה? \u0003אי דגיטא ודמתנתא\u0004 \u0005[אם של גט או של מתנה]\u0006 — \u0003גלויי מילתא בעלמא היא\u0004 \u0005[גילוי דבר בלבד הוא]\u0006 ואין צורך להודיע מה היה האונס, שהרי גט או מתנה אינם ניתנים אלא מרצונו, ואם מודיע שאינו רוצה — בטל הדבר. \u0003ואי דזביני\u0004 \u0005[ואם של מכירה],\u0006 \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003רבא: לא כתבינן מודעא אזביני\u0004 \u0005[אין אנו כותבים\u0006 כלל \u0005מודעה על מכירה]!\u0006","ומשיבים: \u0003לעולם\u0004 מדובר במודעה \u0003דזביני\u0004 \u0005[של מכירה],\u0006 אולם \u0003מודי\u0004 \u0005[מודה]\u0006 \u0003רבא היכא דאניס\u0004 \u0005[במקום ש\u0006הוא \u0005אנוס]\u0006 לעשות זאת, שאם לא כן יפסיד את כספו, \u0003וכמעשה דפרדיסא\u0004 \u0005[של הפרדס]:\u0006 \u0003דההוא גברא דמשכין פרדיסא לחבריה לתלת שנין\u0004 \u0005[שאדם אחד מישכן פרדס לחבירו לשלוש שנים].\u0006 \u0003בתר\u0004 \u0005[אחר]\u0006 ש\u0003אכלה תלת\u0004 \u0005[שלוש]\u0006 \u0003שני\u0004 (שנות) \u0003חזקה, אמר\u0004 המחזיק: \u0003אי מזבנת\u0004 \u0005[אם מוכר אתה]\u0006 \u0003לי\u0004 את השדה — \u0003מוטב, ואי\u0004 \u0005[ואם]\u0006 \u0003לא\u0004 — \u0003כבישנא\u0004 \u0005[אחביא]\u0006 את \u0003שטר\u0004 ה\u0003משכנתא ואמינא\u0004 \u0005[ואומר]\u0006 \u0003\"לקוחה היא בידי\". כהאי גוונא כתבינן\u0004 \u0005[כגון זה כותבים אנו]\u0006 \u0003מודעא\u0004 שהמוכר מודיע מראש שאינו מסכים למכירה, אלא לפי שעה הוכרח למכור.","\u0003אמר רב יהודה: האי מתנתא טמירתא\u0004 \u0005[מתנה נסתרת]\u0006 — \u0003לא מגבינן\u0004 \u0005[\u0006\u0005אין אנו גובים]\u0006 \u0003בה.\u0004 ושואלים: \u0003היכי דמי מתנתא טמירתא\u0004 \u0005[איך היא בדיוק מתנה נסתרת]?\u0006 \u0003אמר רב יוסף: דאמר להו לסהדי\u0004 \u0005[שאומר להם\u0006 הנותן \u0005לעדים]:\u0006 \u0003זילו אטמורו\u0004 \u0005[לכו התחבאו]\u0006 \u0003וכתבו ליה\u0004 \u0005[לו],\u0006 למקבל המתנה שטר מתנה. \u0003ואיכא דאמרי\u0004 \u0005[ויש שאומרים]\u0006 ש\u0003אמר רב יוסף:\u0004 מתנה נסתרת היא כל ש\u0003לא אמר להו\u0004 \u0005[להם]:\u0006 \u0003תיתבו בשוקא ובבריתא\u0004 \u0005[תשבו בשוק ובחוץ]\u0006 \u0003ותכתבו ליה\u0004 \u0005[לו]\u0006 את השטר. ושואלים: \u0003מאי בינייהו\u0004 \u0005[מה\u0006 ההבדל להלכה \u0005ביניהם]\u0006 בין שתי הלשונות הללו? ומשיבים: \u0003איכא בינייהו סתמא\u0004 \u0005[יש ביניהם סתם]\u0006 שלא אמר להם לא להסתתר ולא לעשות זאת בפרסום.","\u0003אמר רבא: ו\u0004מתנה כזו שהוא עושה בסתר, שאין גובים אותה, מכל מקום \u0003הויא\u0004 \u0005[הריהי]\u0006 \u0003מודעא\u0004 וביטול \u0003לחברתה,\u0004 למתנה אחרת, אם נותן אותו דבר עצמו לאדם אחר. \u0003אמר רב פפא: הא\u0004 \u0005[\u0006הלכה \u0005זו]\u0006 שאמר \u0003רבא, לאו\u0004 \u0005[לא]\u0006 \u0003בפירוש איתמר\u0004 \u0005[נאמרה]\u0006 \u0003אלא מכללא איתמר\u0004 \u0005[מכלל\u0006 הדברים \u0005נאמרה]\u0006 ולמדוה מדבריו במקרה מסויים, ואין ללמוד משם הלכה כללית. ומנין למדוה?","ממה \u0003דההוא גברא דאזל לקדושי אתתא\u0004 \u0005[שאדם אחר הלך לקדש אשה],\u0006 \u0003אמרה ליה\u0004 \u0005[לו]:\u0006 \u0003אי כתבת\u0004 \u0005[אם תכתוב]\u0006 \u0003לי\u0004 את \u0003כולהו נכסיך\u0004 \u0005[כל נכסיך]\u0006 במתנה, \u0003הוינא\u0004 \u0005[אהיה]\u0006 \u0003לך\u0004 לאשה, \u0003ואי\u0004 \u0005[ואם]\u0006 \u0003לא\u0004 — \u0003לא הוינא\u0004 \u0005[אהיה]\u0006 \u0003לך\u0004 לאשה. \u0003אזל כתביה לה לכולהו נכסי\u0004 \u0005[הלך\u0006 ו\u0005כתב לה את כל נכסיו].\u0006 \u0003אתא בריה קשישא\u0004 \u0005[בא בנו הגדול],\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003וההוא גברא מה תהוי עליה\u0004 \u0005[ואדם זה,\u0006 אני, \u0005מה יהיה עליו]\u0006 אם אתה נותן את כל נכסיך לאשתך? \u0003אמר להו לסהדי\u0004 \u0005[להם לעדים]:\u0006 \u0003זילו אטמורו\u0004 \u0005[לכו התחבאו]\u0006 \u0003ב\u0004מקום \u0003עבר ימינא וכתבו ליה\u0004 \u0005[לו]\u0006 שטר מתנה על הנכסים. \u0003אתו לקמיה\u0004 \u0005[באו\u0006 העדים לבסוף \u0005לפני]\u0006 \u0003רבא, אמר להו\u0004 \u0005[להם]:\u0006 \u0003לא מר\u0004 \u0005[זה,\u0006 הבן\u0005]\u0006 \u0003קנה\u0004 שהיתה זו מתנה נסתרת, \u0003ולא מר\u0004 \u0005[זה,\u0006 האשה\u0005]\u0006 \u0003קנה.\u0004","ומעירים: \u0003מאן דחזא סבר\u0004 \u0005[מי שראה\u0006 את המעשה \u0005חשב]\u0006 שטעם הדבר שהאשה לא קנתה — \u0003משום דהויא\u0004 \u0005[שהריהי]\u0006 המתנה הנסתרת הזו לבנו, נחשבת \u0003מודעא לחברתה\u0004 למתנה האחרת שנתן לאשה את נכסיו, לבטל אותה. וכך הוא הדין בכל מתנה נסתרת, שאף שאין גובים אותה — משמשת מודעה לחבירתה. \u0003ולא היא\u0004 (ואין הדבר כן), \u0003התם מוכחא מילתא\u0004 \u0005[שם מוכח הדבר]\u0006 ש\u0003מחמת אונסא\u0004 \u0005[אונס]\u0006 \u0003הוא\u0004 ש\u0003כתב לה, אבל הכא\u0004 \u0005[כאן]\u0006 כשנותן מתנה בסתר ופעם אחרת שלא בסתר, ייתכן ש\u0003מר ניחא ליה דליקני\u0004 \u0005[\u0006אדם \u0005זה,\u0006 השני, \u0005נוח לו שיקנה],\u0006 ולכן נתן לו בגלוי, \u0003ומר\u0004 \u0005[וזה]\u0006 \u0003לא ניחא ליה דליקני\u0004 \u0005[נוח לו שיקנה],\u0006 ולכן נתן לו מתנה בסתר, ואין היא מודעה לחבירתה.","\u0003איבעיא להו\u0004 \u0005[נשאלה להם\u0006 ללומדים\u0005]\u0006 שאלה זו:"],["שטר מתנה \u0003סתמא\u0004 \u0005[סתם]\u0006 שאין מפורש בו אם הנותן גילה דעתו לפרסמה, \u0003מאי\u0004 \u0005[מה]\u0006 יהיה דינה? \u0003רבינא אמר: לא חיישינן\u0004 \u0005[אין אנו חוששים]\u0006 שהיא מתנה נסתרת ומתנה גמורה היא, \u0003רב אשי אמר: חיישינן\u0004 \u0005[חוששים אנו].\u0006 \u0003והלכתא\u0004 \u0005[והלכה\u0006 היא\u0005]:\u0006 \u0003חיישינן\u0004 \u0005[חוששים אנו].\u0006","\u0003כל חזקה שאין עמה טענה,\u0004 שטוען המחזיק ומסביר את מהות החזקה, על סמך מה הוא מחזיק — \u0003אינה חזקה. כיצד? אמר לו\u0004 המערער: \u0003מה אתה עושה בתוך\u0004 הקרקע \u0003שלי? והוא\u0004 המחזיק \u0003אמר לו: שלא אמר לי אדם דבר מעולם\u0004 שלא אעשה כן, שלא מחו בי. הרי אף שישב במקום שנות חזקה — \u0003אינה חזקה.\u0004","אבל אם טען \u0003ש\u0004אתה \u0003מכרת לי,\u0004 או \u0003שנתת לי במתנה,\u0004 או \u0003אביך מכרה לי,\u0004 או \u0003אביך נתנה לי במתנה\u0004 — \u0003הרי זו חזקה. ו\u0004עוד אמרו: \u0003הבא משום ירושה\u0004 — \u0003אינו צריך טענה,\u0004 שדי לו שיטען שירש נכס זה, ואינו צריך לפרש כיצד הגיע הנכס לידי מורישו.","על דברי המשנה תוהים: \u0003פשיטא\u0004 \u0005[פשוט]\u0006 הוא שחזקה שאין עימה טענה, אלא רק שלא אמר לו אדם דבר מעולם — אינה חזקה, שהרי אינו טוען לבעלות!","ומשיבים: \u0003מהו דתימא\u0004 \u0005[שתאמר]:\u0006 \u0003האי גברא מיזבן זבנה ליה האי ארעא\u0004 \u0005[אותו אדם,\u0006 המחזיק, באמת \u0005מכרו לו\u0006 הבעלים את \u0005הקרקע הזו],\u0006 \u0003ושטרא\u0004 \u0005[ושטר]\u0006 \u0003הוה ליה ואירכס\u0004 \u0005[היה לו ואבד],\u0006 \u0003והאי דקאמר הכי\u0004 \u0005[וזה שהוא אומר כך]\u0006 שלא אמר לו אדם דבר מעולם, ולא הזכיר את טענת המכירה, \u0003סבר\u0004 \u0005[סבור\u0006 הוא\u0005]:\u0006 \u0003אי אמינא מיזבן זבנה\u0004 \u0005[אם אומר\u0006 ש\u0005מכר אותה]\u0006 \u0003לי האי ארעא\u0004 \u0005[\u0006את \u0005הקרקע הזו],\u0006 \u0003אמרי\u0004 \u0005[יאמרו]\u0006 \u0003לי: אחוי\u0004 \u0005[הראה]\u0006 את \u0003שטרך. הלכך\u0004 היה מקום לומר כי \u0003לימא ליה אנן\u0004 \u0005[נאמר לו אנחנו\u0006 בית הדין\u0005]\u0006 במקרה זה: \u0003דלמא שטרא הוה\u0004 \u0005[שמא שטר היה]\u0006 \u0003לך ואירכס\u0004 \u0005[ואבד],\u0006 משום שמקרה \u0003כגון זה \"פתח פיך לאלם\"\u0004 (משלי לא, ח), \u0003הוא\u0004 ודבר זה בית דין עושים, אף שכרגיל אין טוענים לבעל דין, ועל כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 התנא שבמקרה זה אין אומרים כן, ואין זו חזקה כלל.","\u0003(ענ\"ב סימן)\u0004","מסופר ש\u0003רב ענן שקל בידקא בארעיה\u0004 \u0005[סחף שטף מים באדמתו]\u0006 וגרם לאובדנן של המחיצות בין השדות, \u0003אזל הדר גודא בארעיה דחבריה\u0004 \u0005[הלך חזר\u0006 והקים \u0005מחיצה בקרקע\u0006 שבאמת היתה \u0005של חבירו],\u0006 שהסיג את גבול חבירו שלא מדעת, \u0003אתא לקמיה\u0004 \u0005[בא\u0006 רב ענן \u0005לפני]\u0006 \u0003רב נחמן\u0004 לשאול מה יעשה, \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003זיל הדר\u0004 \u0005[לך החזר]\u0006 את הגבול למקומו הקודם.","אמר לו: \u0003והא אחזיקי לי\u0004 \u0005[והרי\u0006 כבר \u0005החזקתי]\u0006 בקרקע הזו! \u0003אמר ליה\u0004 \u0005[לו]\u0006 רב נחמן: \u0003כמאן\u0004 \u0005[כמי]\u0006 אתה אומר? — \u0003כ\u0004דעת \u0003ר' יהודה ור' ישמעאל דאמרי\u0004 \u0005[שאומרים]\u0006 ש\u0003כל\u0004 שהשתמש בקרקע של חבירו \u0003בפניו, לאלתר הוי\u0004 \u0005[מיד הריהי]\u0006 \u0003חזקה? לית הלכתא כוותייהו\u0004 \u0005[אין הלכה כמותם].\u0006","\u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003והא אחיל\u0004 \u0005[והרי מחל\u0006 לי\u0005],\u0006 וראיה לכך \u0003דאתא\u0004 \u0005[שבא]\u0006 \u0003וסייע בגודא בהדאי\u0004 \u0005[ב\u0006בניית \u0005המחיצה יחד איתי]!\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 רב נחמן: \u0003מחילה בטעות היא, את גופך אי הוה ידעת\u0004 \u0005[אתה עצמך אם היית יודע]\u0006 שאתה מסיג את גבולו \u0003לא עבדת\u0004 \u0005[היית עושה],\u0006 \u0003כי היכי דאת\u0004 \u0005[כמו שאתה]\u0006 \u0003לא הוה ידעת\u0004 \u0005[ידעת],\u0006 \u0003הוא נמי\u0004 \u0005[גם כן]\u0006 \u0003לא הוה ידע\u0004 \u0005[ידע],\u0006 ומה שמחל לך — בטעות היה.","כעין זה מסופר: \u0003רב כהנא שקל בידקא בארעיה\u0004 \u0005[סחף שטף מים בקרקעו].\u0006 \u0003אזל הדר גודא בארעא\u0004 \u0005[הלך חזר\u0006 והקים \u0005מחיצה בקרקע]\u0006 שהתברר אחר כך ש\u0003לא\u0004 היתה \u0003דידיה\u0004 \u0005[שלו].\u0006"],["\u0003אתא לקמיה\u0004 \u0005[בא לפני]\u0006 \u0003רב יהודה, אזיל אייתי תרי סהדי\u0004 \u0005[הלך\u0006 ו\u0005הביא שני עדים],\u0006 \u0003חד\u0004 \u0005[אחד\u0006 מהם\u0005]\u0006 \u0003אמר: תרתי אוצייתא עאל\u0004 \u0005[שתי שורות,\u0006 ערוגות, \u0005נכנס]\u0006 לתוך שדה חבירו, \u0003וחד\u0004 \u0005[ואחד\u0006 מהם\u0005]\u0006 \u0003אמר: תלת אוצייתא עאל\u0004 \u0005[שלוש שורות נכנס],\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 רב יהודה: \u0003זיל שלים תרתי מגו תלת\u0004 \u0005[לך שלם שתים מתוך שלוש\u0006 אלה\u0005],\u0006 כלומר, החזר אותן.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 רב כהנא: \u0003כמאן\u0004 \u0005[כמי]\u0006 אומר אתה שאפשר לסמוך על עדות שיש בה סתירה? השיב לו: \u0003כ\u0004דעת \u0003ר' שמעון בן אלעזר; דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005],\u0006 \u0003אמר ר' שמעון בן אלעזר: לא נחלקו בית שמאי ובית הלל על שתי כיתי\u0004 (קבוצות) \u0003עדים, שאחת אומרת\u0004 שפלוני חייב \u0003מנה\u0004 לחבירו, \u0003ואחת אומרת\u0004 שהוא חייב \u0003מאתים, שיש בכלל מאתים מנה\u0004 ובוודאי צריך לשלם מנה.","\u0003על מה נחלקו?\u0004 — \u0003על כת אחת\u0004 של עדים, \u0003שאחד\u0004 מהעדים \u0003אומר מנה, ואחד אומר מאתים, שבית שמאי אומרים: נחלקה עדותן,\u0004 שאין כאן עדות שלימה של שני עדים על דבר, \u0003ובית הלל אומרים: יש בכלל מאתים מנה\u0004 וישלם מנה. ואני פוסק כבית הלל לשיטה זו.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 רב כהנא: \u0003והא מייתינא\u0004 \u0005[והרי\u0006 יכול \u0005אני להביא]\u0006 \u0003לך איגרתא ממערבא\u0004 \u0005[מכתב מארץ ישראל]\u0006 ש\u0003אין הלכה כר' שמעון בן אלעזר! אמר ליה\u0004 \u0005[לו]\u0006 רב יהודה: \u0003לכי תיתי\u0004 \u0005[לכאשר תביא],\u0006 ובינתיים צריך אתה לנהוג כפי שפסקתי.","\u0003ההוא גברא דדר\u0004 \u0005[אדם אחד שגר]\u0006 \u0003בקשתא בעיליתא\u0004 \u0005[בעליית גג]\u0006 \u0003ארבע שני\u0004 \u0005[שנים],\u0006 \u0003אתא מארי דביתא אשכחיה\u0004 \u0005[בא בעל הבית מצא אותו],\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003מאי בעית בהאי ביתא\u0004 \u0005[מה אתה מבקש,\u0006 מה מעשיך, \u0005בבית זה]?\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003מפלניא זבינתה דזבנה מינך\u0004 \u0005[מפלוני קניתי אותה שקנה אותה ממך],\u0006 \u0003אתא לקמיה\u0004 \u0005[בא\u0006 המחזיק \u0005לפני]\u0006 \u0003ר' חייא, אמר ליה\u0004 \u0005[לו]:\u0006 \u0003אי אית\u0004 \u0005[אם יש]\u0006 \u0003לך סהדי\u0004 \u0005[עדים]\u0006 ש\u0003דר בה\u0004 בדירה זו \u0003איהו דזבנת מיניה\u0004 \u0005[אותו שקנית ממנו]\u0006 \u0003ואפילו חד יומא\u0004 \u0005[יום אחד]\u0006 — \u0003אוקימנא לה\u0004 \u0005[\u0006\u0005מעמיד אני אותה]\u0006 \u0003בידך, ואי\u0004 \u0005[ואם]\u0006 \u0003לא\u0004 — \u0003לא\u0004 אעשה כן ותחזור העליה לבעליה.","\u0003אמר רב: הוה יתיבנא קמיה דחביבי\u0004 \u0005[הייתי יושב לפני דודי,\u0006 ר' חייא\u0005],\u0006 \u0003ואמרי ליה\u0004 \u0005[ואמרתי לו]:\u0006 מדוע תלוי הדבר בכך? \u0003וכי אין אדם עשוי ליקח\u0004 (לקנות) \u0003ולמכור ב\u0004אותו \u0003לילה\u0004 עצמו, ואם כן, ייתכן שלא היה המוכר אפילו לילה אחד בדירה, אף שבאמת קנאה! \u0003וחזיתיה לדעתיה\u0004 \u0005[וראיתי לדעתו]\u0006 הבנתי מדבריו ש\u0003אי אמר ליה\u0004 \u0005[אם היה אומר לו]\u0006 המחזיק: \u0003קמאי דידי זבנה מינך\u0004 \u0005[בפני שלי\u0006 ראיתי ש\u0005קנה אותה ממך]\u0006 — היה \u0003מהימן\u0004 \u0005[נאמן],\u0006 \u0003מיגו דאי בעי אמר ליה\u0004 \u0005[מתוך שאם היה רוצה\u0006 לשקר \u0005היה יכול לומר לו]:\u0006 \u0003אנא זבנתה מינך\u0004 \u0005[אני קניתי אותה ממך].\u0006","\u0003אמר רבא: כוותיה\u0004 \u0005[כשיטתו]\u0006 של \u0003ר' חייא מסתברא\u0004 \u0005[מסתבר],\u0006 \u0003דקתני\u0004 \u0005[ששנינו]:\u0006 \u0003הבא משום ירושה\u0004 — \u0003אינו צריך טענה,\u0004 ונדייק מכאן: \u0003טענה הוא\u0004 ש\u0003לא בעי\u0004 \u0005[צריך],\u0006 לטעון בוודאות שאביו קנאה — \u0003הא\u0004 \u0005[הרי]\u0006 \u0003ראיה בעי\u0004 \u0005[\u0006הוא \u0005צריך]\u0006 שהיה הדבר בידי מורישו.","ודוחים: \u0003ודלמא\u0004 \u0005[ושמא]\u0006 \u0003לא ראיה בעי\u0004 \u0005[\u0006הוא \u0005צריך]\u0006 \u0003ולא טענה בעי\u0004 \u0005[\u0006הוא \u0005צריך]!\u0006 ולא אמר שאינו צריך טענה אלא להבדיל בין מקרה זה לבין חזקה שאין עמה טענה. \u0003ואיבעית אימא\u0004 \u0005[ואם תרצה אמור]:\u0006 אף אם יורש צריך ראיה שמורישו דר במקום — \u0003שאני\u0004 \u0005[שונה]\u0006 \u0003לוקח\u0004 (קונה) \u0003דלא שדי זוזי בכדי\u0004 \u0005[שאינו זורק כסף בחינם],\u0006 וכיון ששילם עבור הדבר, בוודאי בירר שהיתה לו למוכר זכות בו.","\u0003איבעיא להו\u0004 \u0005[נשאלה להם\u0006 ללומדים\u0005]:\u0006 אם \u0003נראה בו\u0004 המוכר מסתובב באותה קרקע, \u0003מאי\u0004 \u0005[מה]\u0006 יהא הדין? האם יש מכאן ראיה ללוקח שקנאה המוכר מן הבעלים? \u0003אמר אביי: היא היא\u0004 \u0005[הוא הוא],\u0006 כלומר, הרי זה כאילו הוכח שהחזיק בה. \u0003רבא אמר: עביד איניש דסיאר ארעיה ולא זבין\u0004 \u0005[עשוי אדם שמסייר קרקע ואינו קונה\u0006 אותה\u0005]\u0006 ולכן העובדה שהיה במקום אינה הוכחה שאכן קנה אותו, אלא אם כן השתמש בו כבשלו.","\u0003שלשה לקוחות מצטרפין\u0004 לענין חזקה. שאם קנו זה מזה, והחזיקו כולם יחד שלוש שנים — הרי הם כחזקה אחת. \u0003אמר רב: וכולם\u0004 צריך שיקנו זה מזה \u0003בשטר\u0004 שאז מתפרסם הדבר, והבעלים הראשונים יודעים על כך, ויכולים לבוא ולמחות.","ושואלים: \u0003למימרא\u0004 \u0005[האם לומר]\u0006 מכאן ש\u0003סבר רב\u0004 ש\u0003שטר אית ליה קלא\u0004 \u0005[יש לו קול]\u0006 ומתפרסם, \u0003ועדים\u0004 בלבד \u0003לית להו קלא\u0004 \u0005[אין להם קול]?\u0006 \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003רב: המוכר שדה בעדים\u0004 אף שלא כתב שטר, אם ניטל השדה מיד הקונה משום שהיה שיעבוד מוקדם על השדה — \u0003גובה\u0004 הקונה קרקע במקומה \u0003מנכסים משועבדים,\u0004 כלומר, נכסים שמכר המוכר לאחר שמכר לו שדה זו. ומכאן שאנו מניחים שהיה פרסום למכירה זו, וידעו הקונים האחרים ששדות המוכר משועבדים כבר! ומשיבים: \u0003התם\u0004 \u0005[שם],\u0006 \u0003לקוחות\u0004"],["\u0003אינהו אפסידו אנפשייהו\u0004 \u0005[הם הפסידו על עצמם]\u0006 שהיה ראוי להם לחקור אם אין הקרקע שהם רוצים לקנות משועבדת.","ומקשים: \u0003ומי\u0004 \u0005[והאם]\u0006 \u0003אמר רב הכי\u0004 \u0005[כך]\u0006 שעל פי עסקה שנעשית בעדים גובים מנכסים משועבדים? \u0003והתנן\u0004 \u0005[והרי שנינו\u0006 במשנה\u0005]:\u0006 \u0003המלוה את חבירו בשטר\u0004 — \u0003גובה מנכסים משועבדים,\u0004 שהם נכסים שמכר הלווה לאחר ההלוואה, אם אין ללווה נכסים. אבל המלוה \u0003על ידי עדים\u0004 בלא שטר — \u0003גובה\u0004 רק \u0003מנכסים בני חורין!\u0004","\u0003וכי תימא\u0004 \u0005[ואם תאמר]\u0006 כדי לפתור קושיה זו ש\u0003רב\u0004 עצמו \u0003תנא הוא ופליג\u0004 \u0005[וחולק]\u0006 על המשנה הזו, \u0003והא\u0004 \u0005[והרי]\u0006 \u0003רב ושמואל דאמרי תרוייהו\u0004 \u0005[שאומרים שניהם]:\u0006 \u0003מלוה על פה\u0004 אף על פי שנעשה בעדים — \u0003אינו גובה לא מן היורשים ולא מן הלקוחות!\u0004","ומתרצים: מ\u0003מלוה אזביני קא רמית\u0004 \u0005[על מכר אתה משליך,\u0006 מראה סתירה\u0005]?\u0006 \u0003מלוה, כי קא יזיף\u0004 \u0005[כאשר הוא לווה]\u0006 — \u0003בצנעא קא יזיף\u0004 \u0005[בצנעה הוא לווה],\u0006 \u0003כי היכי\u0004 \u0005[כדי]\u0006 ש\u0003לא ליתזלו נכסיה עליה\u0004 \u0005[יוזלו נכסיו עליו],\u0006 שאם ידעו הכל שהוא נזקק לכסף, הרי כשירצה למכור את נכסיו יציעו לו מחירים נמוכים יותר. והואיל שלווה ממון בצינעה — אין גובים מלקוחות. אבל \u0003זביני, מאן דזבין ארעא\u0004 \u0005[מכר, מי שקונה קרקע]\u0006 — \u0003בפרהסיא זבין\u0004 \u0005[בפרהסיא\u0006 הוא \u0005קונה],\u0006 \u0003כי היכי דליפוק לה קלא\u0004 \u0005[כדי שיצא על כך קול],\u0006 ואף אם נעשה הדבר בעדים בלבד — יש לדבר פרסום, ולכן אין להקשות מהלוואה על מכר.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003אכלה האב שנה והבן\u0004 שירש ממנו אכלה \u0003שתים,\u0004 או שאכלה \u0003האב שתים והבן שנה,\u0004 או \u0003האב שנה והבן שנה והלוקח\u0004 (הקונה) מן הבן \u0003שנה\u0004 — \u0003הרי זו חזקה.\u0004","ושואלים: \u0003למימרא\u0004 \u0005[האם לומר]\u0006 מכאן ש\u0003לוקח אית ליה קלא\u0004 \u0005[יש לו קול]\u0006 ומתפרסם הדבר שקנה? \u0003ורמינהי\u0004 \u0005[ומשליכים,\u0006 מראים סתירה\u0005],\u0006 ממה ששנינו: מי שהחזיק בקרקע בדרך זו: ש\u0003אכלה בפני האב שנה ובפני הבן שתים,\u0004 או \u0003בפני האב שתים ובפני הבן שנה,\u0004 או \u0003בפני האב שנה ובפני הבן שנה ובפני\u0004 ה\u0003לוקח\u0004 מן הבן \u0003שנה\u0004 — \u0003הרי זו חזקה. ואי סלקא דעתך\u0004 \u0005[ואם עולה על דעתך]\u0006 לומר כי \u0003לוקח אית ליה קלא\u0004 \u0005[יש לו קול],\u0006 \u0003אין לך מחאה גדולה מזו,\u0004 שהרי הבעלים מוכרים את הנכס שאדם זה מחזיק בו לאדם אחר, ובוודאי שזו מחאה גמורה על המחזיק בנכסיהם שלא כדין!","\u0003אמר רב פפא: כי תניא ההיא\u0004 \u0005[כאשר שנויה אותה\u0006 ברייתא\u0005]\u0006 שיש חזקה גם אם נמכר השדה לאחר על ידי הבעלים — הרי זה \u0003במוכר שדותיו סתם,\u0004 שהבן לא מכר במפורש שדה זה שהלה מחזיק בו, אלא מכר את כל שדותיו. והמחזיק סבור שאת השדה הזה לא מכר בכללם, ולכן אינו נזהר לשמור את שטרו, ואחרי שלוש שנים מועילה לו החזקה. אך אם היה הבן מוכר במפורש שדה זה — יש בכך מחאה.","\u0003האומנין\u0004 המחזיקים בביתם כלים שהם מתקנים, \u0003והשותפין, והאריסין\u0004 בקרקע, \u0003והאפוטרופין\u0004 של נכסי יתומים — \u0003אין להם חזקה\u0004 באותם דברים שהם מחזיקים בהם, שהרי יתכן שהם מחזיקים בהם רק מכוח אומנות או שותפות וכו'. וכיוצא בזה אין חזקה \u0003לא לאיש חזקה בנכסי אשתו, ולא לאשה חזקה בנכסי בעלה, ולא לאב בנכסי הבן, ולא לבן בנכסי האב,\u0004 כיון שהם משתמשים זה בשל זה ברשות, ואין בכך כל הוכחה להעברת בעלות.","\u0003במה דברים אמורים?\u0004 — \u0003במחזיק,\u0004 כאשר החזקה משמשת לו ראיה לבעלות. \u0003אבל בנותן מתנה,\u0004 ויש עדים על מתנה זו, \u0003ו\u0004כן \u0003האחין שחלקו\u0004 ירושת אביהם, וכל אחד רוצה להחזיק בחלקו, \u0003והמחזיק בנכסי הגר\u0004 שמת, שלא היו לו יורשים, ובמותו נעשו נכסיו הפקר, אם \u0003נעל\u0004 את דלת הנכס, או \u0003גדר,\u0004 או \u0003פרץ\u0004 מן הגדר \u0003כל שהוא\u0004 — \u0003הרי\u0004 פעולה \u0003זו\u0004 עצמה היא מעשה \u0003חזקה\u0004 של קנין, ועל ידה נקנית לו הבעלות."],["\u0003אבוה\u0004 \u0005[אביו]\u0006 של \u0003שמואל ו\u0004כן \u0003לוי תנו\u0004 \u0005[שנו]:\u0006 \u0003שותף אין לו חזקה, וכל שכן אומן.\u0004 ואילו \u0003שמואל תני\u0004 \u0005[שנה]:\u0006 \u0003אומן אין לו חזקה, אבל שותף יש לו חזקה. ואזדא\u0004 \u0005[והולך]\u0006 \u0003שמואל לטעמיה\u0004 \u0005[לטעמו,\u0006 לשיטתו\u0005],\u0006 ש\u0003אמר שמואל: השותפין מחזיקין,\u0004 יש להם חזקה \u0003זה על זה, ומעידין זה על זה, ונעשים שומרי שכר זה לזה,\u0004 שלעניינים אלה הם נחשבים כשני אנשים זרים.","\u0003רמי ליה\u0004 \u0005[השליך לו,\u0006 הראה לו סתירה\u0005]\u0006 \u0003ר' אבא לרב יהודה במערתא דבי\u0004 \u0005[במערה של בית]\u0006 \u0003רב זכאי, מי\u0004 \u0005[האם]\u0006 \u0003אמר שמואל: שותף יש לו חזקה? והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003שמואל: שותף\u0004 המשתמש בנכס המשותף כולו \u0003כיורד\u0004 לנכסי חבירו \u0003ברשות דמי\u0004 \u0005[נחשב].\u0006 \u0003לאו למימרא\u0004 \u0005[האם לא\u0006 התכוון \u0005לומר]\u0006 בכך ש\u0003שותף אין לו חזקה?\u0004 ודוחים: \u0003לא קשיא\u0004 \u0005[אין\u0006 זה \u0005קשה]:\u0006 \u0003הא דנחית\u0004 \u0005[זה שירד]\u0006 \u0003ל\u0004כל השדה \u0003כולה, הא דנחית לפלגא\u0004 \u0005[זה שירד למחציתה].\u0006","ובפירוש דבר זה \u0003אמרי לה להאי גיסא, ואמרי לה להאי גיסא\u0004 \u0005[\u0006יש \u0005אומרים אותה לצד זה,\u0006 ויש \u0005אומרים אותה לצד זה],\u0006 שיש מקום לומר כי שותף שהחזיק שלוש שנים רק מחצית השדה, הרי זו הוכחה שזה הוא חלקו הקנוי רק לו, אבל אם ירד לכולה במשך שלוש שנים — אין לו חזקה, שכך נוהגים שותפים.","ואפשר לומר להיפך, שאם יורד רק למחצית — אינה חזקה. אבל אם מחזיק בכולה שלוש שנים — ראיה היא שכולה שלו היא. \u0003רבינא אמר: הא והא דנחית\u0004 \u0005[זה וזה\u0006 מדובר, \u0005כשירד]\u0006 \u0003ל\u0004כל השדה \u0003כולה, ולא קשיא\u0004 \u0005[קשה]:\u0006 \u0003הא\u0004 \u0005[זה]\u0006 מדובר \u0003דאית\u0004 \u0005[שיש]\u0006 \u0003בה\u0004 בקרקע גודל מספיק שיהיה בה \u0003דין חלוקה,\u0004 ולכן השותף המשתמש בכולה הרי זה נכנס בחלק שהוא ודאי של חבירו, ואם לא מחה בידו — יש לו חזקה. \u0003הא דלית\u0004 \u0005[זו שאין]\u0006 \u0003בה דין חלוקה,\u0004 ולכן גם אם נכנס לכולה, כיון שאין חלקה זו מתחלקת והכל שייך לשניהם, אף אם נכנס לכולה אין זו הוכחה לבעלות, אלא נכנס רק משום השותפות.","\u0003גופא\u0004 \u0005[\u0006דנים \u0005לגופו]\u0006 של הדבר שהזכרנו קודם, \u0003אמר שמואל: שותף כיורד ברשות דמי\u0004 \u0005[נחשב].\u0006 ושואלים: \u0003מאי קא משמע לן\u0004 \u0005[מה השמיע לנו\u0006 בכך\u0005],\u0006 ש\u0003שותפות אין לו חזקה?\u0004 אם כן \u0003לימא\u0004 \u0005[שיאמר]\u0006 במפורש: \u0003שותף אין לו חזקה!\u0004","\u0003אמר רב נחמן אמר רבה בר אבוה: לומר\u0004 שאם עשה דברים מדעת עצמו בשדה השותפות, כגון שנטע וגידל עצי פרי שם \u0003שנוטל בשבח המגיע לכתפים\u0004 גם מחלק חבירו, שכל הגידולים שגידל באדמה זו, אם הגיעו לדרגה שהם בשלים ואפשר לקחת אותם על הכתפיים, מקבל את חלקו בהם. ואינו נדון בשדה זו כמי שירד לשדה שלא ברשות בעל הבית, שידו על התחתונה ואינו מקבל יותר מהוצאותיו. ודין זה חל \u0003בשדה שאינה עשויה ליטע\u0004 במטעים, אלא לזריעה, והוא בכל זאת נטע בה, \u0003כ\u0004מו ב\u0003שדה העשויה ליטע.\u0004","בין דברי שמואל לעיל נזכר כי השותפים \u0003מעידין זה לזה,\u0004 שאם יערער אדם על חלקו של אחד מהם בשדה — יכול השני, בצירוף עד נוסף, להעיד לטובתו, ואינו נחשב כנוגע בעדותו."],["ושואלים: \u0003אמאי\u0004 \u0005[מדוע]\u0006 יכולים הם להעיד? הלא \u0003נוגעין בעדותן הן,\u0004 שכל אחד מהם הוא שותף בדבר שהוא מעיד עליו!","ומשיבים: \u0003הכא במאי עסקינן\u0004 \u0005[כאן במה אנו עוסקים]?\u0006 — באופן \u0003דכתב ליה\u0004 \u0005[שכותב לו]\u0006 שותף אחד לחבירו: \u0003\"דין ודברים אין לי\u0004 מעתה \u0003על שדה זו\u0004 שדנים עליה \u0003\",\u0004 כלומר, שהוא מסלק עצמו מכל חלק ושותפות בה. ושואלים: \u0003וכי כתב\u0004 \u0005[וכאשר כותב]\u0006 \u0003לו מאי הוי\u0004 \u0005[מה בכך]?\u0006 האם מועיל הדבר? \u0003והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]:\u0006 \u0003האומר לחבירו\u0004 שותפו: \u0003\"דין ודברים אין לי על שדה זו\" ו\u0004כן אם אמר \u0003\"אין לי עסק בה\" ו\u0004כן \u0003\"ידי מסולקות הימנה\"\u0004 — \u0003לא אמר כלום,\u0004 שאמירות אלה אין להן תוקף משפטי!","ומשיבים: \u0003הכא במאי עסקינן\u0004 \u0005[כאן במה אנו עוסקים]?\u0006 — \u0003כשקנו מידו,\u0004 כשעשו ביניהם השותפים מעשה קנין על ויתורו של האחד על כל זכות בשדה זה, ואז יש תוקף של הקנאה גמורה לשותפו בויתור זה, ואם עשה כן אינו עוד נוגע בעדותו. ושואלים: \u0003וכי\u0004 \u0005[וכאשר]\u0006 \u0003קנו מידו מאי הוי\u0004 \u0005[מה בכך]?\u0006 והלא בעדות זו שמעיד לטובת השותף (לשעבר) אף הוא נהנה, ש\u0003הרי\u0004 בכך הוא \u0003מעמידה בפני בעל חובו,\u0004 שאם היה חייב כסף לאדם אחר קודם שהסתלק מן הקרקע, יוכל בעל חובו לגבות את החוב מקרקע זו שביד השותף, שכבר נשתעבדה למלוה, ולפיכך הריהו נוגע בעדות,","ש\u0003אמר רבין בר שמואל משמיה\u0004 \u0005[משמו]\u0006 של \u0003שמואל: המוכר שדה לחבירו\u0004 אף \u0003שלא באחריות\u0004 (שהתנה שלא יחזור הקונה ויגבה ממנו את תמורת השדה אם יתברר ששדה זו של אדם אחר היא) ונמצא שאין לו נגיעה בדבר, מכל מקום — \u0003אין מעיד לו\u0004 לקונה \u0003עליה\u0004 שהיא של הקונה, \u0003מפני ש\u0004בכך \u0003מעמידה\u0004 לגביה \u0003בפני בעל חובו\u0004 שלו.","ומשיבים: \u0003הכא במאי עסקינן\u0004 \u0005[כאן\u0006 בשותף שנסתלק מן הקרקע \u0005במה אנו עוסקים]?\u0006 — באופן \u0003דקביל עליה\u0004 \u0005[שקיבל עליו]\u0006 \u0003אחריות\u0004 לפצות את שותפו, אם תילקח הקרקע שנתן לו. ונמצא שאינו מרויח דבר אם יעיד לטובת השותף. ושואלים: \u0003אחריות דמאן\u0004 \u0005[של מי]?\u0006 \u0003אי נימא\u0004 \u0005[אם תאמר]\u0006 \u0003אחריות דעלמא\u0004 \u0005[של אחרים],\u0006 שהתנה שאם יטען אדם אחר לבעלות על הקרקע ויקחנה יחזיר לו סכום זה — \u0003כל שכן\u0004 שנוגע בעדותו, \u0003דניחא ליה\u0004 \u0005[שנוח לו]\u0006 בזה שהקרקע נשארת ביד חבירו, משום שבכך הוא נפטר מן הצורך לפצותו! \u0003אלא\u0004 יש לומר: שקיבל עליו \u0003אחריות דאתיא ליה מחמתיה\u0004 \u0005[שתבוא לו מחמת עצמו],\u0006 כלומר, שאם בגלל חובו שלו יבואו לגבות את השדה — יפצה את השותף. ולפי זה אין לו כל הנאה בעדותו, שהרי בין כה וכה יצטרך לשלם את חובו.","ושואלים לעצם הפתרון: \u0003וכי\u0004 \u0005[וכאשר]\u0006 שותף \u0003מסלק נפשיה מיניה\u0004 \u0005[את עצמו ממנו,\u0006 מחלקו בדבר\u0005]\u0006 \u0003מי\u0004 \u0005[האם]\u0006 הוא באמת \u0003מסתלק\u0004 ואינו נחשב נוגע בדבר? \u0003והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]:\u0006 \u0003בני עיר שנגנב ספר תורה שלהן\u0004 ונתפס הגנב, והוא טוען שספר התורה שייך לו, \u0003אין דנין\u0004 את הענין הזה \u0003בדייני אותה העיר, ואין מביאין ראיה\u0004 (כלומר, אין מקבלים עדות) \u0003מאנשי אותה העיר,\u0004 מפני שכולם נוגעים בדבר. \u0003ואם איתא\u0004 \u0005[יש]\u0006 מקום לדין זה של סילוק, \u0003ליסלקו בי תרי מינייהו ולידיינו\u0004 \u0005[שיסתלקו שניים מהם\u0006 מזכותם בספר התורה, \u0005וידונו]!\u0006","ודוחים: \u0003שאני\u0004 \u0005[שונה]\u0006 \u0003ספר תורה\u0004 ש\u0003לשמיעה קאי\u0004 \u0005[\u0006הוא \u0005עומד]\u0006 והכל חייבים לשמוע את הקריאה בו, ולכן גם אם מסתלקים מבעלות עליו, מכל מקום אינם מסתלקים מהנאה ממנו.","ומציעים, \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה מברייתא אחרת: \u0003האומר \"תנו מנה לבני עירי\"\u0004 — \u0003אין דנין\u0004 בדין מתנה זו \u0003בדייני אותה העיר, ואין מביאין ראיה מאנשי אותה העיר,\u0004 ואם הסתלקות מועילה לענין עדות \u0003אמאי\u0004 \u0005[מדוע]\u0006 אין דנים בהם? \u0003ליסלקו בי תרי נפשייהו ולידיינו\u0004 \u0005[שיסלקו שניים\u0006 את \u0005עצמם\u0006 מליהנות ממנה זה \u0005וידונו\u0006 בו\u0005]!\u0006","ומשיבים: \u0003הכא נמי\u0004 \u0005[כאן גם כן]\u0006 מדובר \u0003ב\u0004כסף שניתן לצורך \u0003ספר תורה.\u0004","ומציעים, \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה אחרת לדבר: \u0003האומר \"תנו מנה לעניי עירי\"\u0004 — \u0003אין דנין בדייני אותה העיר ואין מביאין ראיה מאנשי אותה העיר.\u0004 ותחילה תוהים על לשון הברייתא: \u0003ותסברא\u0004 \u0005[וכי סבור אתה]\u0006 כי \u0003עניים שקלי\u0004 \u0005[נוטלים,\u0006 מקבלים\u0005]\u0006 את הצדקה ואילו \u0003דייני מיפסלי\u0004 \u0005[הדיינים נפסלים]\u0006 על ידי כך? \u0003אלא אימא\u0004 \u0005[אמור]\u0006 ותקן כך: \u0003אין דנין בדייני עניי אותה העיר,\u0004 כלומר, אם היו הדיינים בעצמם מעניי העיר אי אפשר לדון על ידם, משום שהם נוגעים בדבר, \u0003ו\u0004כך גם \u0003אין מביאים ראיה מעניי אותה העיר.\u0004 ולאחר שיישבנו את לשון הברייתא חוזרים להקשות ממנה: \u0003ואמאי\u0004 \u0005[ומדוע]\u0006 אומרים כן? הרי יש דרך אחרת: \u0003לסתלקו בי תרי נפשייהו ולידיינו\u0004 \u0005[שיסלקו שניים מהם\u0006 את \u0005עצמם\u0006 ממתנות אלה \u0005וידונו]!\u0006","ומשיבים: \u0003הכא נמי\u0004 \u0005[כאן גם כן]\u0006 מדובר \u0003בספר תורה\u0004 שאותו אדם תרם את הכסף עבור ספר תורה לבני עירו. \u0003ואמאי קרי להו\u0004 \u0005[ומדוע קרא להם]\u0006 \u0003\"עניים\"?\u0004 ש\u0003הכל אצל ספר תורה עניים הן,\u0004 משום שהספרים יקרים ואינם מצויים.","\u0003ואיבעית אימא\u0004 \u0005[ואם תרצה אמור]:\u0006 \u0003לעולם כדקתני\u0004 \u0005[כפי ששנה]\u0006 והמשמעות היא שנתן מתנה עבור \u0003עניים ממש, ו\u0004מדובר \u0003בעניי דראמו עלייהו\u0004 \u0005[בעניים שמוטלים עליהם]\u0006 על אנשי העיר כולם, וחייבים לפרנסם, ולפיכך נוגעים הם בדבר. ומבררים: \u0003והיכי דמי\u0004 \u0005[כיצד הוא בדיוק]\u0006 ענין של עניים המוטלים עליהם? \u0003אי דקיץ להו\u0004 \u0005[אם שקצוב להם]\u0006 סכום הצדקה, שכל אחד מבני העיר נותן לעניים, \u0003ליתבו בי תרי מינייהו מאי דקיץ להו ולידיינו\u0004 \u0005[שיתנו שניים מהם מה שקצוב להם\u0006","לעניים \u0005וידונו],\u0006 שהרי שוב אינם נוגעים בדבר! ומשיבים: \u0003הכא במאי עסקינן\u0004 \u0005[כאן במה אנו עוסקים]?\u0006 — באופו ש\u0003לא קיץ להו\u0004 \u0005[קצוב להם]\u0006 סכום מסויים, אלא העניים מקבלים לפי צרכיהם, ועדיין החובה לדאוג לעניים אלו מוטלת על בני העיר. \u0003ואיבעית אימא\u0004 \u0005[ואם תרצה אמור]:\u0006 \u0003לעולם דקיץ להו\u0004 \u0005[שקצוב להם]\u0006 סכום מסויים \u0003ו\u0004מכל מקום \u0003ניחא להו\u0004 \u0005[נוח להם]\u0006 לבני העיר שהמתנה ניתנת לעניים, ש\u0003כיון\u0004 ש\u0003רווח\u0004 להם עתה \u0003רווח\u0004 עוד, וצדקה זו — מקילה את העול מעל אנשי העיר.","עוד אמר שמואל שהשותפים \u0003נעשין שומרי שכר זה לזה.\u0004"],["ושואלים: \u0003אמאי\u0004 \u0005[מדוע]?\u0006 הלא \u0003שמירה בבעלים היא,\u0004 שהרי כל אחד מהם מחוייב כלפי השני בשמירת החפצים המשותפים, וכלל הוא שאם הבעלים עובדים עבור השומר — אינו חייב באחריות! \u0003אמר רב פפא:\u0004 מדובר במקרה \u0003דאמר ליה\u0004 \u0005[שאומר לו]\u0006 השותף: \u0003שמור לי היום ואני אשמור לך למחר,\u0004 ונמצא שבכל יום כל אחד מהם הוא השומר היחידי של הדברים, ואין כאן שמירה בבעלים.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 אם \u0003מכר לו\u0004 לחבירו \u0003בית,\u0004 או \u0003מכר לו שדה\u0004 — \u0003אין מעיד לו עליה\u0004 אם יבוא אדם אחר ויטען ששלו הוא, \u0003מפני שאחריותו עליו\u0004 שאם יזכה התובע בשדה יצטרך הוא לפצות את הקונה, ולכן הוא נחשב כנוגע בדבר. אבל אם \u0003מכר לו פרה\u0004 או \u0003מכר לו טלית\u0004 — \u0003מעיד לו עליה, מפני שאין אחריותו עליו.\u0004 ושואלים: \u0003מאי שנא רישא ומאי שנא סיפא\u0004 \u0005[מה שונה ההתחלה ומה שונה הסוף]?\u0006 מדוע מניחים שיש לו אחריות יתירה על הבית יותר מאשר על הפרה?","\u0003אמר רב ששת: רישא\u0004 \u0005[בתחילה]\u0006 מדובר \u0003בראובן שגזל שדה משמעון ומכרה ללוי, ואתא\u0004 \u0005[ובא]\u0006 אדם נוסף \u0003יהודה, וקא מערער\u0004 וטוען שהשדה שלו היא, ועל כך אומרת הברייתא ש\u0003לא ליזיל\u0004 \u0005[ילך]\u0006 \u0003שמעון\u0004 הנגזל \u0003לאסהיד ליה\u0004 \u0005[להעיד לו]\u0006 \u0003ללוי\u0004 שאכן השדה שייכת ללוי בדין, משום שנוגע הוא בדבר, \u0003דניחא ליה דהדרא\u0004 \u0005[שנוח לו שתחזור\u0006 השדה\u0005]\u0006 ללוי, כדי שאחר כך יוכל להוציאה מידו.","ושואלים: \u0003וכיון דאסהיד ליה\u0004 \u0005[שהעיד לו]\u0006 לשדה זו כי של \u0003לוי הוא, היכי מצי מפיק לה מיניה\u0004 \u0005[כיצד יוכל להוציא אותה\u0006 לבסוף \u0005ממנו]?\u0006 ומשיבים: מדובר במקרה ש\u0003אמר\u0004 בעדותו לטובת לוי: \u0003ידענא דהאי ארעא דלאו\u0004 \u0005[יודע אני שקרקע זו לא]\u0006 של \u0003יהודה היא,\u0004 אבל אינו מעיד במפורש שהיא של לוי, וכך יש לו אפשרות להוציא את הקרקע מיד לוי. ושואלים: \u0003ובההוא זכותא דקא מפיק לה\u0004 \u0005[ובאותה זכות שהוא מוציא אותה]\u0006 \u0003מלוי, ליפקה\u0004 \u0005[שיוציא אותה]\u0006 \u0003מיהודה\u0004 עצמו, ומדוע נחשוד בו שהוא נוגע בדבר כאשר מעיד לטובת לוי?","ומשיבים: יש לחשוש \u0003דאמר\u0004 \u0005[שאומר]\u0006 שמעון זה בלבו: \u0003השני\u0004 (כלומר, לוי) \u0003נוח לי\u0004 ואותו אוכל לתבוע לאחר זמן, ו\u0003הראשון\u0004 (יהודה) \u0003קשה הימנו,\u0004 ולא אוכל להוציא מידו.","\u0003ואי בעית אימא\u0004 \u0005[ואם תרצה אמור]\u0006 כי מדובר במקרה שלא יוכל להוציא את הקרקע מיד יהודה, אם תגיע לידו, ו\u0003כגון\u0004 באופן \u0003דאית ליה סהדי למר ואית ליה סהדי למר\u0004 \u0005[שיש לו עדים לזה ויש לו עדים לזה],\u0006 שיש עדים לשמעון שהשדה היא שלו, אבל גם יהודה מביא עדים שהשדה שייכת לו, \u0003ואמור רבנן\u0004 \u0005[ואמרו חכמים]\u0006 שבמקרה כזה \u0003ארעא היכא דקיימא תיקום\u0004 \u0005[הקרקע היכן שעומדת תעמוד]\u0006 ותישאר ברשות המחזיק בה. ולכן מעונין שמעון שהשדה תישאר בידי לוי ויוציאנה מידיו, וכשתהא בידיו — שוב לא יוכל יהודה להוציאה ממנו. ובמקרה כזה נוגע שמעון בדבר, ואינו יכול להעיד לטובת לוי."],["ושואלים: אם כדברי רב ששת, ברייתא זו עוסקת בנגזל שאינו יכול להעיד לטובת המחזיק בקרקעו, מדוע להעמיד זאת במי שמכר לו הגזלן את הקרקע? \u0003ולוקמה\u0004 \u0005[ושיעמיד אותה]\u0006 התנא \u0003בגזלן\u0004 עצמו, שאין הנגזל רשאי להעיד עליה לטובתו, משום שיש לו נגיעה בדבר, שסבור שיוכל להוציא ממנו את הקרקע!","ומשיבים: \u0003משום דקא בעי למיתנא סיפא\u0004 \u0005[שרצה לשנות\u0006 את \u0005הסוף]:\u0006 \u0003מכר לו פרה, מכר לו טלית\u0004 — מעיד לו עליה, ששם מדובר \u0003דוקא\u0004 בגזלן ש\u0003מכר, דהוה ליה\u0004 \u0005[שהרי הוא,\u0006 שיש בכך\u0005]\u0006 גם \u0003יאוש\u0004 בעלים בגזילה, \u0003ו\u0004גם \u0003שינוי רשות,\u0004 ואז איבד הנגזל את זכותו לגוף החפץ הגזול, וממילא אין לו נגיעה בדבר, ויכול להעיד לטובת הקונה. \u0003אבל\u0004 אם \u0003לא מכר,\u0004 ואין כאן שינוי רשות, \u0003דהדרא ליה\u0004 \u0005[שחוזרת אליו]\u0006 הגזילה — \u0003לא\u0004 רשאי להעיד עליה לטובת הגזלן, שהרי הוא עדיין נוגע בדבר, שרצונו שיהא החפץ ביד הגזלן ויוכל אחר כך להוציא ממנו. משום כך \u0003תנא רישא נמי\u0004 \u0005[שנה\u0006 ב\u0005ראש גם כן]\u0006 במקרה ש\u0003מכר.\u0004","ומקשים: \u0003וסיפא נמי נהי דמייאש מגופיה, מדמיה מי מייאש\u0004 \u0005[ובסוף גם כן,\u0006 שהעמדנו ביאוש ושינוי רשות, \u0005אם אמנם שהתייאש מגופו\u0006 של החפץ, \u0005מדמיו האם מתייאש]?\u0006 שאף שעל ידי יאוש ושינוי רשות איבד את זכותו לחפץ, הרי זה לענין הזכות על גוף החפץ, אבל לא לענין התביעה לדמיו, ונמצא שיש לו עדיין נגיעה בדבר! ומשיבים: \u0003לא צריכא\u0004 \u0005[נצרכה]\u0006 אלא במקרה \u0003דמית\u0004 \u0005[שמת]\u0006 ה\u0003גזלן,\u0004 ואז אינו יכול לתבוע אף את דמי הגזילה, \u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]:\u0006 \u0003הגוזל ומאכיל את בניו,\u0004 \u0003ו\u0004כן אם \u0003הניח לפניהם\u0004 בירושה — \u0003פטורים\u0004 הבנים \u0003מלשלם.\u0004 וכיון שכך נמצא שאין לנגזל כל זכות עוד על החפץ, ויכול להעיד לטובת הקונה.","ושואלים: אם כך הוא, ולשיטת רב ששת בהכרח מדובר כאן בגזלן שמת, מדוע העמיד התנא מקרה בו מכר הגזלן את הגזילה לאדם אחר? \u0003ולוקמה\u0004 \u0005[ושיעמיד אותה,\u0006 את כל הברייתא\u0005]\u0006 \u0003ביורש\u0004 מן הגזלן בעצמו, שאם הוריש לו קרקע, שלעולם חוזרת לבעליה — אין הנגזל מעיד עליה לטובתו, מפני שאז יכול להוציא מידו. ואם היה זה חפץ — יכול להעיד לטובתו, משום שממילא לא יוכל לדרוש ממנו דבר!","ומעירים: \u0003הניחא למאן דאמר\u0004 \u0005[\u0006אמנם \u0005זה נוח ל\u0006שיטת \u0005מי שאומר]\u0006 ש\u0003רשות יורש לאו\u0004 \u0005[לא]\u0006 \u0003רשות לוקח דמי\u0004 \u0005[נחשבת]\u0006 שהיורש נחשב כהמשכו של המוריש ולא כקונה — \u0003שפיר\u0004 \u0005[יפה],\u0006 מפני שהחפץ נחשב כאילו נשאר ברשות הגזלן, וחייב היורש להחזירו לנגזל. \u0003אלא למאן דאמר\u0004 \u0005[ל\u0006שיטת \u0005מי שאומר]\u0006 ש\u0003רשות יורש כרשות לוקח דמי\u0004 \u0005[נחשבת],\u0006 \u0003מאי איכא למימר\u0004 \u0005[מה יש לומר]?\u0006 הרי, כאמור, ניתן להעמיד את הדברים במקרה פשוט של גזלן שמת והוריש את הגזילה לבניו!","\u0003ועוד קשיא ליה\u0004 \u0005[היה קשה לו]\u0006 \u0003לאביי\u0004 על עיקר פירושו של רב ששת, שברייתא זו עוסקת בגזילה, וקושי זה בא מצד הנימוק שנותנת הברייתא לדין זה: וכי טעם ההבדל בין שני המקרים בברייתא הוא \u0003מפני שאחריותו עליו ואין אחריותו עליו?\u0004 הרי \u0003מפני שהיא\u0004 (הגזילה) \u0003חוזרת לו\u0004 לנגזל \u0003ואינה חוזרת לו מיבעי ליה\u0004 \u0005[צריך היה לו\u0006 לומר\u0005]!\u0006","\u0003אלא\u0004 יש לדחות את דברי רב ששת, ולפרש את הברייתא \u0003כ\u0004מו שאמר \u0003רבין בר שמואל,\u0004 ש\u0003אמר רבין בר שמואל משמיה\u0004 \u0005[משמו]\u0006 של \u0003שמואל: המוכר שדה לחבירו,\u0004 ואף \u0003שלא באחריות\u0004 — בכל זאת \u0003אין\u0004 המוכר \u0003מעיד לו\u0004 לטובת הקונה \u0003עליה,\u0004 אם בא אדם אחד וטוען לבעלות עליה. ואף שלא יצטרך לפצות אותו אם יזכה בה האחר, מכל מקום יש לו נגיעה בדבר, \u0003מפני שמעמידה בפני בעל חובו,\u0004 שאם השדה נשארת ביד הקונה — יכול בעל חובו של המוכר לגבות ממנו.","\u0003ו\u0004ממשיכה הברייתא ומוסיפה כי דין זה הוא \u0003דוקא\u0004 ב\u0003בית או שדה\u0004 מפני שמעמידם בפני בעל חובו שיכול לגבות מהם, \u0003אבל פרה וטלית, לא מיבעיא\u0004 \u0005[נצרכה\u0006 לומר\u0005]\u0006"],["\u0003בסתמא דלא משתעבדא ליה\u0004 \u0005[\u0006בהלוואה \u0005בסתם, שאין\u0006 הפרה או הטלית \u0005משועבדת לו]\u0006 למלוה\u0005.\u0006 \u0003מאי טעמא\u0004 \u0005[\u0006ו\u0005מה טעם\u0006 הדבר\u0005]\u0006 — \u0003מטלטלי נינהו\u0004 \u0005[\u0006\u0005מיטלטלים הם],\u0006 \u0003ומטלטלי\u0004 \u0005[ומיטלטלים]\u0006 \u0003לבעל חוב לא משתעבדי\u0004 \u0005[משתעבדים].\u0006 \u0003ואף על גב דכתב ליה\u0004 \u0005[ואף על פי שכותב לו]\u0006 בשטר שיכול לגבות את החוב אף \u0003מגלימא\u0004 \u0005[מגלימה]\u0006 ש\u0003על כתפיה\u0004 \u0005[כתיפו],\u0006 \u0003הני מילי דאיתנהו בעינייהו\u0004 \u0005[דברים אלה\u0006 אמורים דווקא \u0005שנמצאים\u0006 החפצים \u0005בעינם]\u0006 והם ברשות הלווה, \u0003אבל\u0004 אם הם \u0003ליתנהו בעינייהו\u0004 \u0005[אינם בעינם]\u0006 — \u0003לא,\u0004 ואין איפוא נגיעה למוכר להעיד בעניינם, משום שבעל חובו לא יגבה מהם.","\u0003אלא אפילו\u0004 אם \u0003עשאו\u0004 את החפץ המיטלטל \u0003אפותיקי נמי\u0004 \u0005[אחריות מפורשת\u0006 לפרעון חובו, \u0005גם כן]\u0006 \u0003לא\u0004 גובה מהם, \u0003מאי טעמא\u0004 \u0005[מה טעם\u0006 הדבר\u0005]?\u0006 — \u0003כ\u0004דברי \u0003רבא,\u0004 ש\u0003אמר רבא:\u0004 אם \u0003עשה\u0004 את \u0003עבדו\u0004 (הכנעני) \u0003אפותיקי\u0004 להלוואה \u0003ומכרו\u0004 לאחר — \u0003בעל חוב גובה ממנו\u0004 ולוקח את העבד לעצמו. אבל אם עשה את \u0003שורו וחמורו אפותיקי ומכרו\u0004 — \u0003אין בעל חוב גובה הימנו,\u0004","\u0003מאי טעמא\u0004 \u0005[מה טעם\u0006 הדבר\u0005]?\u0006 — \u0003האי\u0004 \u0005[זה]\u0006 עבד שנמכר \u0003אית ליה קלא\u0004 \u0005[יש לו קול],\u0006 והדבר מתפרסם והקונה יודע שהוא קונה עבד שיש עליו שיעבוד, \u0003והא לית ליה קלא\u0004 \u0005[וזה,\u0006 שאר מיטלטלים, \u0005אין לו קול].\u0006 ולכן בכל מקרה שמכר מיטלטלים יכול להעיד עליהם לטובת הקונה, שהרי אינו מרויח בכך דבר, משום שאינם משועבדים לבעל חובו.","ושואלים: \u0003וליחוש דלמא אקני ליה מטלטלי אגב מקרקעי\u0004 \u0005[ונחשוש שמא הקנה לו\u0006 למלוה, לצורך שיעבוד, \u0005מיטלטלים אגב הקרקעות],\u0006 ועל ידי זה שיעבד את המיטלטלים לפרעון חובו. ש\u0003אמר רבה: אי אקני ליה מטלטלי אגב מקרקעי\u0004 \u0005[אם הקנה לו מיטלטלים אגב קרקעות]\u0006 לשם שיעבוד — הרי אם \u0003קני מקרקעי קני מטלטלי\u0004 \u0005[קנה קרקעות קנה מיטלטלים],\u0006 \u0003ואמר רב חסדא: והוא\u0004 ש\u0003כתב ליה\u0004 \u0005[לו\u0006 למלוה\u0005]\u0006 בשטר השיעבוד: \u0003\"\u0004ש\u0003לא\u0004 יהיה זה \u0003כ\u0004שטר \u0003אסמכתא\u0004 שאין קונים בו וש\u0003לא כטופסא דשטרי\"\u0004 \u0005[כטופס של שטרות]\u0006 שאינו עשוי לגבייה, אלא שטר בעל תוקף!","ומשיבים: \u0003הכא במאי עסקינן\u0004 \u0005[כאן במה אנו עוסקים]?\u0006 \u0003כגון שלקח\u0004 (קנה) מוכר פרה או טלית זו \u0003ומכר לאלתר\u0004 \u0005[מיד],\u0006 ולא היה זמן שיכול היה ללוות ולשעבד אותה לאחרים.","ושואלים: \u0003וליחוש דילמא\u0004 \u0005[ונחשוש שמא]\u0006 שטר זה, שטר \u0003\"דאיקני\"\u0004 \u0005[\"שאקנה\"]\u0006 \u0003הוא,\u0004 שאף שלווה קודם לכן שיעבד מראש אגב הקרקע לא רק דברים המצויים עתה ברשותו, אלא גם דברים שיקנה בעתיד, ונמצא שבשעה שקנה — מיד נשתעבדה הפרה או הטלית לבעל חובו! האם \u0003שמעת מינה\u0004 \u0005[שומע אתה מכאן\u0006 מן הברייתא\u0005]\u0006 פתרון לשאלה שנשארה במקומה בלא תשובה, שמי ששיעבד נכסיו והתחייב על דברים \u0003\"דאיקני\"\u0004 \u0005[\"שאקנה\"],\u0006 אם \u0003קנה ומכר, קנה והוריש\u0004 — \u0003לא משתעבד?\u0004 שהרי אם היה משתעבד — יש לו נגיעה בדבר.","ומשיבים: \u0003לא צריכא\u0004 \u0005[נצרכה],\u0006 אלא במקרה \u0003דקאמרי\u0004 \u0005[שאומרים]\u0006 ה\u0003עדים: ידעינן ביה בהאי\u0004 \u0005[יודעים אנו בזה]\u0006 ש\u0003לא הוה ליה ארעא\u0004 \u0005[היתה לו קרקע]\u0006 \u0003מעולם,\u0004 ואם כן לא יכול היה לשעבד את המיטלטלים אגב קרקע, שהרי לא היתה לו קרקע מעולם. ואין מכאן הוכחה.","ומקשים: גם כך, עדיין יש למוכר הפרה או הטלית ענין להעיד לטובת הקונה — כדי שלא יתבע אותו הקונה עצמו, \u0003והאמר\u0004 \u0005[והרי\u0006 כך \u0005אמר]\u0006 \u0003רב פפא: אף על גב דאמור רבנן\u0004 \u0005[אף על פי שאמרו חכמים]:\u0006 \u0003המוכר שדה לחבירו שלא באחריות ובא בעל חוב וטרפה\u0004 — \u0003אינו חוזר עליו\u0004 הקונה על המוכר, שאינו יכול לתבוע ממנו לפצותו. אבל אם \u0003נמצאת\u0004 השדה \u0003שאינה שלו\u0004 מתחילה — \u0003חוזר עליו\u0004 שלא היתה זו מכירה כלל. והוא הדין לפרה או לטלית, אם יוכיח המערער ששלו היתה, וממילא לא היתה של המוכר, ומדוע יכול המוכר להעיד לטובת הקונה?","ומשיבים: \u0003הכא במאי עסקינן\u0004 \u0005[כאן במה אנו עוסקים]\u0006 — \u0003ב\u0004קונה ה\u0003מכיר בה\u0004 בבהמה זו \u0003שהיא בת חמורו\u0004 של המוכר, ומודה בכך, ומכירה זו אינה חוזרת, ואם כן, אין למוכר נגיעה בדבר.","\u0003ורב זביד אמר: אפילו נמצאת שאינה שלו\u0004 — \u0003אינו חוזר עליו\u0004 הקונה, \u0003דאמר ליה\u0004 \u0005[שאומר לו]\u0006 המוכר: \u0003להכי זביני\u0004 \u0005[משום כך מכרתי]\u0006 \u0003לך שלא באחריות,\u0004 כדי שלא תחזור עלי בטענות בכל מקרה.","\u0003גופא\u0004 \u0005[לגופה]\u0006 של ההלכה שהזכרנו, \u0003אמר רבין בר שמואל משמיה\u0004 \u0005[משמו]\u0006 של \u0003שמואל: המוכר שדה לחבירו שלא באחריות\u0004 — \u0003אין מעיד לו\u0004 המוכר \u0003עליה, מפני ש\u0004בעדותו הוא \u0003מעמידה\u0004 לגבייה \u0003בפני בעל חובו.\u0004 ומבררים: \u0003היכי דמי\u0004 \u0005[כיצד בדיוק היה הדבר]?\u0006"],["\u0003אי דאית ליה ארעא אחריתי\u0004 \u0005[אם\u0006 במקרה \u0005שיש לו\u0006 למוכר־הלווה \u0005קרקע אחרת]\u0006 שאפשר לגבות ממנה, הלא \u0003עליה דידיה הדר\u0004 \u0005[עליו עצמו\u0006 הוא \u0005חוזר\u0006 לגבות\u0005]\u0006 ואינו נוגע בעדות לגבי הקרקע שמכר! \u0003אי דלית ליה ארעא אחריתי\u0004 \u0005[אם\u0006 במקרה \u0005שאין לו קרקע אחרת],\u0006 \u0003מאי נפקא ליה מינה\u0004 \u0005[מה יוצא לו מזה,\u0006 מה זה משנה\u0005]?\u0006","הרי בין כה וכה אי אפשר לגבות ממנו את החוב! ומשיבים: \u0003לעולם\u0004 מדובר במקרה \u0003דלית ליה ארעא אחריתי\u0004 \u0005[שאין לו קרקע אחרת],\u0006 ובכל זאת אנו חוששים שיש לו נגיעה בדבר, \u0003דאמר\u0004 \u0005[ש\u0006הוא \u0005אומר]:\u0006 \u0003לא ניחא דליהוי\u0004 \u0005[נוח\u0006 לי \u0005שאהיה]\u0006 בגדר של \u0003\"לוה רשע ולא ישלם\"\u0004 (תהלים לז, כא), ויש לו ענין שיוכל בעל חובו לגבות את החוב מן השדה.","ומקשים: \u0003סוף סוף לגבי אידך נמי\u0004 \u0005[אצל האחר\u0006 שקנה ממנו את הקרקע \u0005[גם כן],\u0006 הרי בגדר של \u0003\"לוה רשע ולא ישלם\" הוא,\u0004 שקיבל ממנו כסף ולא נתן תמורה, שהרי הקרקע תופקע מן הקונה על ידי בעל החוב! ומשיבים: לזה אינו חושש, לפי \u0003דאמר\u0004 \u0005[שאומר]\u0006 לו: \u0003להכי זביני\u0004 \u0005[משום כך מכרתי]\u0006 \u0003לך שלא באחריות,\u0004 וידעת מראש שיש סיכון בדבר זה.","היה \u0003מכריז רבא\u0004 ברבים, \u0003ואיתימא\u0004 \u0005[ויש אומרים]\u0006 שהיה מכריז זאת \u0003רב פפא: דסלקין לעילא ודנחתין לתתא\u0004 \u0005[העולים למעלה והיורדים למטה],\u0006 כלומר, העולים מבבל לארץ ישראל, והיורדים מארץ ישראל לבבל, דעו כולכם דין זה: \u0003האי בר ישראל דזבין ליה חמרא\u0004 \u0005[בן ישראל זה שמוכר לו חמור]\u0006 \u0003לישראל חבריה\u0004 \u0005[חבירו],\u0006 \u0003וקא אתי\u0004 \u0005[ובא]\u0006 \u0003גוי ואניס ליה מיניה\u0004 \u0005[ואונס אותו,\u0006 לוקח\u0005, ממנו]\u0006 את החמור, שהגוי טוען שחמור זה שלו הוא, ולא של הישראל שמכרו, \u0003דינא\u0004 \u0005[הדין]\u0006 \u0003הוא דמפצי ליה מיניה\u0004 \u0005[ש\u0006המוכר \u0005ילך ויציל אותו ממנו],\u0006","ואם לא — ישלם לקונה את כספו, שהרי בעקיפין גרם הוא שיילקח החמור מיד הקונה. ומעירים: \u0003ולא אמרן\u0004 \u0005[אמרנו]\u0006 דבר זה שעליו לפצותו \u0003אלא\u0004 בקונה \u0003שאינו מכיר בה שהיא בת חמורו\u0004 של המוכר, שיש מקום לומר שהגוי צודק, ובאמת נמכר לו דבר גזול, \u0003אבל\u0004 אם \u0003מכיר בה שהיא בת חמורו\u0004 — \u0003לא,\u0004 שאז מסתבר שהגוי בא רק בעלילת שוא, ואין המוכר אחראי לכך. ועוד, \u0003ולא אמרן\u0004 \u0005[אמרנו]\u0006 דבר זה שעליו לפצותו \u0003אלא\u0004 במקרה \u0003דלא אניס ליה לדידיה ולאוכפא\u0004 \u0005[שאינו אונס\u0006 ולוקח גם \u0005אותו\u0006 את החמור \u0005ואת האוכף],\u0006 \u0003אבל\u0004 אם \u0003אניס ליה לדידיה ולאוכפא\u0004 \u0005[אונס\u0006 גם \u0005אותו ואת האוכף]\u0006 — \u0003לא,\u0004 משום שדבר זה מוכיח שגוי זה גזלן הוא, ובא בתואנת שוא, ואין הדבר תלוי במוכר.","\u0003אמימר אמר:\u0004 \u0003אפילו\u0004 אם \u0003ליכא\u0004 \u0005[אין]\u0006 \u0003כל הני\u0004 \u0005[האלה]\u0006 התנאים — \u0003לא\u0004 חייב לפצותו, ורואים זאת כאונס סתם. \u0003מאי טעמא\u0004 \u0005[מה טעם\u0006 הדבר\u0005]?\u0006 — \u0003מידע ידע\u0004 \u0005[ידוע\u0006 הדבר\u0005]\u0006 ש\u0003סתם גוי אנס הוא, שנאמר\u0004 בהם: \u0003\"אשר פיהם דבר שוא וימינם ימין שקר\"\u0004 (תהלים קמד, ח).","שנינו במשנה ש\u0003אומן אין לו חזקה וכו',\u0004 שאינו יכול לטעון שחפץ שנתן לו הבעלים לתיקון, שלו הוא, שמכרו לו בעליו. \u0003אמר רבה: לא שנו אלא שמסר לו\u0004 הבעלים את החפץ לאומן \u0003בעדים,\u0004 ויכולים הבעלים להוכיח שהחפץ היה שלהם ונמסר לאומן לשם תיקון. \u0003אבל\u0004 אם \u0003מסר לו\u0004 את החפץ \u0003שלא בעדים, מתוך שיכול\u0004 האומן \u0003לומר לו \"לא היו דברים מעולם\u0004 והחפץ היה שלי תמיד \u0003\",\u0004 \u0003כי אמר ליה נמי\u0004 \u0005[כאשר אומר לו גם כן]\u0006 \u0003\"לקוחה\u0004 (קנויה) \u0003היא בידי\"\u0004 — \u0003מהימן\u0004 \u0005[נאמן\u0006 הוא\u0005].\u0006","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי: אי הכי\u0004 \u0005[אם כך]\u0006 אתה מסביר, \u0003אפילו\u0004 מסרו לאומן \u0003בעדים נמי\u0004 \u0005[גם כן]\u0006 יהיה האומן נאמן, כיצד? \u0003מתוך שיכול לומר לו\u0004 לבעלים: אמנם לקחתי אותו בעדים, אבל אחר כך \u0003החזרתיו לך\u0004 ואין החפץ עוד בידי, \u0003כי אמר ליה\u0004 \u0005[כאשר אומר לו]\u0006 \u0003\"לקוחה היא בידי\"\u0004 — גם כן \u0003מהימן\u0004 \u0005[נאמן]!\u0006","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבה: מי סברת\u0004 \u0005[האם סבור אתה]\u0006"],["ש\u0003המפקיד אצל חבירו בעדים\u0004 — \u0003אינו צריך להחזיר לו בעדים,\u0004 ומשום כך יכול לטעון שהחזיר? \u0003לא סלקא דעתך\u0004 \u0005[לא יעלה על דעתך]\u0006 כך \u0003אלא המפקיד אצל חבירו בעדים, צריך להחזיר לו בעדים,\u0004 ולכן אינו יכול לטעון שהחזיר אם אין לו עדים על כך.","\u0003מיתיבי\u0004 \u0005[מקשה]\u0006 \u0003אביי\u0004 ממה ששנינו בברייתא: \u0003ראה עבדו ביד אומן\u0004 או \u0003טליתו ביד כובס,\u0004 ו\u0003אומר לו: מה טיבו אצלך?\u0004 ואומר לו המחזיק \u0003\"אתה מכרתו לי\",\u0004 או \u0003\"אתה נתתו לי במתנה\"\u0004 — \u0003לא אמר כלום,\u0004 וחייב להחזיר לו, שהרי כפי ששנינו אין לאומן חזקה. אבל אם אמר האומן \u0003\"בפני אמרת לו\u0004 לאדם אחר \u0003למוכרו וליתנו לו\u0004 (לי) \u0003במתנה\"\u0004 — \u0003דבריו קיימין.\u0004","ולפני הצגת הקושיה, מבררים את הברייתא: \u0003מאי שנא רישא ומאי שנא סיפא\u0004 \u0005[מה שונה ההתחלה\u0006 שהאומן אינו נאמן, \u0005ומה שונה הסוף]\u0006 שיהא האומן נאמן?","\u0003אמר רבה: סיפא\u0004 \u0005[\u0006ב\u0005סוף]\u0006 מדובר \u0003ביוצא\u0004 (נמצא) העבד או הטלית \u0003מתחת ידי אחר\u0004 ולא מתחת יד האומן, \u0003וקאמר ליה\u0004 \u0005[ואומר לו]\u0006 ה\u0003אחר: בפני אמרת לו\u0004 לאומן \u0003למוכרו\u0004 או \u0003ליתנו\u0004 לי \u0003במתנה,\u0004 והטעם שנאמן בדבריו, אף שמודה שלקח מן האומן: \u0003מיגו דאי בעי אמר ליה\u0004 \u0005[מתוך שאם היה רוצה\u0006 היה יכול \u0005לומר לו]\u0006 \u0003\"מינך זבנתיה\"\u0004 \u0005[ממך\u0006 במישרין \u0005קניתי אותו],\u0006 ונאמן היה בדבר, שהרי איננו אומן. \u0003כי אמר ליה נמי\u0004 \u0005[כאשר אומר לו גם כן]\u0006 \u0003\"בפני אמרת לו למוכרו\"\u0004 — \u0003דבריו קיימין,\u0004 \u0003ומהימן\u0004 \u0005[ונאמן].\u0006","ולעצם השאלה: \u0003קתני מיהת רישא\u0004 \u0005[שונה\u0006 הוא \u0005על כל פנים\u0006 ב\u0005ראש\u0006 הברייתא\u0005]:\u0006 \u0003ראה\u0004 עבדו ביד אומן או טליתו ביד כובס, רק אז אין האומן נאמן, ונברר: \u0003היכי דמי\u0004 \u0005[כיצד בדיוק היה הדבר]?\u0006 \u0003אי דאיכא\u0004 \u0005[אם שיש]\u0006 עדים שמסר לו את העבד לאימון או את הטלית לכיבוס, \u0003למה לי ראה? ניתי\u0004 \u0005[שיביא]\u0006 \u0003עדים\u0004 שמסר לו לשם כך \u0003ונשקול\u0004 \u0005[ויקח]\u0006 את שלו! \u0003אלא לאו דליכא\u0004 \u0005[האם לא\u0006 מדובר \u0005שאין]\u0006 \u0003עדים, וכי ראה מיהא תפיס ליה\u0004 \u0005[וכאשר רואה על כל פנים\u0006 הוא \u0005תופס אותו]!\u0006 ומכאן משמע שלא כדברי רבה שהדבר תלוי במסירה בעדים, אלא די בכך שרואה ממש את חפציו בידי האומן.","ודחה רבה: \u0003לא, לעולם\u0004 מדובר \u0003דאיכא\u0004 \u0005[שיש]\u0006 \u0003עדים\u0004 על מסירת החפץ, אלא שיש לכך עוד תנאי נוסף: \u0003והוא דראה\u0004 \u0005[שרואה]\u0006 עכשיו את החפץ בידו.","הקשה לו אביי: \u0003והא את\u0004 \u0005[והרי אתה\u0006 עצמך\u0005]\u0006 \u0003הוא\u0004 ש\u0003אמרת: המפקיד אצל חבירו בעדים, צריך לפורעו\u0004 (להחזיר לו) \u0003בעדים,\u0004 ולדבריך אם מסר לו בעדים, די במה שאין לו עדים שהחזיר לו! \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003הדרי\u0004 \u0005[חזרתי]\u0006 \u0003בי\u0004 מסברה זו, אבל עדיין אני מחזיק בדעתי שמדובר במשנתנו דוקא במוסר לאומן בעדים, ואם אין עדים על כך — יש לאומן חזקה.","\u0003מתיב\u0004 \u0005[מקשה]\u0006 \u0003רבא לסיועי\u0004 \u0005[לסייע]\u0006 \u0003לרבה\u0004 ממה ששנו בברייתא: \u0003הנותן טליתו לאומן\u0004 לתיקון, \u0003אומן אומר: שתים\u0004 (שני דינרים) \u0003קצצת\u0004 (קצבת) \u0003לי\u0004 כשכר, \u0003והלה אומר: לא קצצתי לך אלא אחת. כל זמן שהטלית ביד אומן\u0004 — \u0003על בעל הבית להביא ראיה.\u0004 ואם \u0003נתנה לו\u0004 האומן, יש לחלק: אם תובעו \u0003בזמנו,\u0004 כלומר, ביום שהשיב לו את הטלית — \u0003נשבע\u0004 האומן \u0003ונוטל.\u0004 אם \u0003עבר זמנו\u0004 ובא ותובע שכרו לאחר הזמן — \u0003המוציא מחבירו עליו הראיה.\u0004","ונברר: \u0003היכי דמי\u0004 \u0005[כיצד בדיוק היה הדבר]?\u0006 \u0003אי דאיכא\u0004 \u0005[אם שיש]\u0006 \u0003עדים\u0004 בזמן שנמסרה הטלית לאומן, \u0003ליחזי\u0004 \u0005[שיראו]\u0006 את ה\u0003עדים מאי קאמרי\u0004 \u0005[מה הם אומרים],\u0006 שמן הסתם גם הם שמעו כמה קצב לו בשכרו."],["\u0003אלא לאו\u0004 \u0005[האם לא]\u0006 מדובר \u0003דליכא\u0004 \u0005[שאין]\u0006 \u0003עדים\u0004 שמסר לו, \u0003וקתני\u0004 \u0005[ושנה]:\u0006 \u0003אומן מהימן\u0004 \u0005[נאמן].\u0006 והטעם הוא: \u0003מיגו דאי בעי אמר ליה\u0004 \u0005[מתוך שאם היה רוצה\u0006 היה \u0005אומר לו]\u0006 \u0003\"לקוחה היא בידי\", מהימן נמי אאגריה\u0004 \u0005[נאמן גם כן על שכרו],\u0006 והרי זו הוכחה לשיטת רבה, שאם לא נמסר בעדים יכול האומן לטעון שהוא שלו!","ודוחים: \u0003לא, לעולם\u0004 אפשר לפרש כי מדובר גם \u0003דליכא\u0004 \u0005[שאין]\u0006 \u0003עדים,\u0004 ובנוסף לכך \u0003והוא\u0004 בלבד ש\u0003לא ראה\u0004 את הטלית ביד האומן, ויכול הלה לטעון \"לא היו דברים מעולם\".","אבל אם היתה הטלית בידיו של האומן — לא היה האומן נאמן. \u0003מתיב\u0004 \u0005[מקשה]\u0006 \u0003רב נחמן בר יצחק\u0004 על דברי רבה, ממה ששנינו במשנתנו: \u0003אומן אין לו חזקה.\u0004 ונדייק מכאן: \u0003אומן הוא\u0004 ש\u0003אין לו חזקה, הא\u0004 \u0005[הרי]\u0006 \u0003אחר\u0004 במקרה כגון זה \u0003יש לו חזקה.\u0004","ונברר: \u0003היכי דמי\u0004 \u0005[כיצד בדיוק מדובר]?\u0006 \u0003אי דאיכא\u0004 \u0005[אם שיש]\u0006 \u0003עדים\u0004 שראו כיצד נמסר החפץ (כפקדון, או בהשאלה), \u0003אחר אמאי\u0004 \u0005[מדוע]\u0006 \u0003יש לו חזקה?\u0004 הרי יש עדים שאינו שלו! \u0003אלא לאו\u0004 \u0005[האם אין]\u0006 מדובר \u0003דליכא\u0004 \u0005[שאין]\u0006 \u0003עדים, וקתני\u0004 \u0005[ושנה]:\u0006 \u0003אומן אין לו חזקה,\u0004 משמע שאין לו חזקה בכל מקרה. ואם כן \u0003תיובתא\u0004 \u0005[קושיה חמורה]\u0006 היא ל\u0003רבה!\u0004 ומסכמים: אכן, \u0003תיובתא\u0004 \u0005[קושיה חמורה\u0006 היא\u0005]\u0006 ונדחו דבריו.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003נתחלפו לו כלים בכלים בבית האומן,\u0004 שקיבל מן האומן חפץ שאינו שלו — \u0003הרי זה ישתמש בהן\u0004 בכלים שניתנו לו, \u0003עד שיבא הלה,\u0004 בעל אותם הכלים, \u0003ויטול את שלו.\u0004 אבל אם נתחלפו לו בגדים \u0003בבית האבל או בבית המשתה\u0004 שבאים אנשים רבים בבת אחת, ופעמים שטועים ולוקחים בגד עליון שאינו שלהם — \u0003הרי זה לא ישתמש בהן עד שיבא הלה,\u0004 בעל הבגד, \u0003ויטול את שלו.\u0004 ושואלים: \u0003מאי שנא רישא ומאי שנא סיפא\u0004 \u0005[מה שונה ההתחלה ומה שונה הסוף],\u0006 מדוע מותר לו להשתמש בכליו של אחר שהגיעו לידיו מבית האומן, ולא באלה שלקח בטעות בבית האבל או בבית המשתה?","\u0003אמר רב: הוה יתיבנא קמיה דחביבי\u0004 \u0005[הייתי יושב לפני דודי]\u0006 ר' חייא, \u0003ואמר לי\u0004 טעם הדברים: \u0003וכי אין אדם עשוי לומר לאומן \"מכור לי\u0004 (בשבילי) את \u0003טליתי\"?\u0004 כלומר, יתכן שאדם אחר ביקש מן האומן: לאחר שתתקן את הטלית אני מבקשך למכור אותה ולתת לי את התמורה. ואם כן יתכן שהאומן טעה ומכר במקומה את טליתו של זה, ומחזיר לו במקומה את הטלית שניתנה לו לצורך מכירה. והואיל והאחר מקבל את כספו — זכותו של האומן לתת לזה את הטלית בינתיים. מה שאין כן בבית האבל או בבית המשתה, שנעשה הדבר בטעות, והאחר מחפש עדיין את טליתו.","\u0003אמר רב חייא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב נחמן: לא שנו\u0004 שמותרים הכלים בשימוש \u0003אלא\u0004 ש\u0003הוא,\u0004 האומן עצמו נתן לו כלי של אחר, שאז יש מקום לסברה זו שהאומן נותן דבר שיש לו רשות עליו. \u0003אבל\u0004 אם קיבל חפץ של אחר מיד \u0003אשתו ובניו\u0004 של האומן — \u0003לא,\u0004 שמסתבר לומר שטעו והחליפו. \u0003והוא\u0004 האומן עצמו שנתן \u0003נמי\u0004 \u0005[גם כן]\u0006 \u0003לא אמרן\u0004 \u0005[אמרנו]\u0006 \u0003אלא דאמר ליה\u0004 \u0005[שאומר לו]\u0006 האומן: \u0003\"\u0004אני נותן לך \u0003טלית\" סתם,\u0004 אבל אם אמר לו \u0003\"\u0004אני נותן לך את \u0003טליתך\"\u0004 — \u0003לא,\u0004 כי \u0003האי לאו\u0004 \u0005[זו לא]\u0006 \u0003טלית דידיה הוא\u0004 \u0005[שלו היא]\u0006 וטעות של חילופין היתה כאן.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי לרבא: תא אחוי\u0004 \u0005[בוא\u0006 ו\u0005אראה]\u0006 \u0003לך רמאי\u0004 העיר \u0003פומבדיתא מאי עבדי\u0004 \u0005[מה\u0006 הם \u0005עושים],\u0006 \u0003אמר ליה\u0004 \u0005[אומר לו]\u0006 אחד לחבירו: \u0003הב לי\u0004 את \u0003סרבלאי\u0004 \u0005[גלימתי]\u0006 שמסרתי לך לתקן, אומר לו המקבל: \u0003לא היו דברים מעולם.\u0004 אומר לו הנותן: \u0003הא אית\u0004 \u0005[הרי יש]\u0006 \u0003לי סהדי דחזיוה גבך\u0004 \u0005[עדים שראו אותה אצלך]!\u0006 \u0003אמר ליה\u0004 \u0005[אומר לו]:\u0006 הבגד \u0003ההוא\u0004 שראו בגד \u0003אחרינא הוה\u0004 \u0005[אחר היה],\u0006 ובאמת, העדים שראו אינם יכולים להיות בטוחים לחלוטין שהיה זה של הטוען. אומר לו המפקיד: \u0003אפקיניה ונחזינהו\u0004 \u0005[הוצא אותו ונראה אותו]\u0006 ויעידו העדים אם שלי הוא! \u0003אמר ליה\u0004 \u0005[אומר לו]\u0006 האומן: \u0003איברא\u0004 \u0005[באמת]\u0006 \u0003לא מפיקנא ליה\u0004 \u0005[אוציא אותו]\u0006 בשבילך, כי אין ממש בטענותיך, ואיני הולך להראות לך את הבגדים של אחרים לצורך זה.","\u0003אמר רבא: שפיר קאמר ליה\u0004 \u0005[יפה אומר לו],\u0006 כלומר, אף שאולי רמאים הם, טענה זו טענה של ממש היא, שהרי"],["במקרה ש\u0003ראה תניא\u0004 \u0005[שנויה]\u0006 הברייתא לעיל: ראה טליתו ביד כובס, ואמר לו הכובס \"אתה מכרתו לי\" — לא אמר כלום. כלומר, דווקא כשהוא עצמו ראה את החפץ ויכול לזהותו בוודאות יכול הוא לבוא בתביעה, אבל אם לא ראו בוודאות את הדבר, אינו יכול לתבוע על סמך השערה.","\u0003אמר רב אשי: ואי חכים\u0004 \u0005[ואם\u0006 בעל החפץ הוא \u0005חכם]\u0006 — \u0003משוי ליה\u0004 \u0005[\u0006יכול הוא \u0005לעשות זאת]\u0006 באופן שיהיה ויתקיים מצב כזה של \u0003ראה,\u0004 כיצד? \u0003דאמר ליה\u0004 \u0005[שאומר לו]:\u0006 \u0003אמאי תפיסת ליה\u0004 \u0005[מדוע אתה תופס]\u0006 את הבגד שלי, \u0003לאו\u0004 \u0005[האם\u0006 \u0003לא]\u0004 \u0003משום דאית\u0004 \u0005[שיש]\u0006 \u0003לך\u0004 כסף שהלוית \u0003גבאי\u0004 \u0005[אצלי]?\u0006 \u0003השתא אפקינהו ושימינהו, שקול את דידך ואשקול אנא דידי\u0004 \u0005[עכשיו הוצא אותם,\u0006 את הבגדים, \u0005ונאמוד\u0006 את שויים, \u0005קח אתה\u0006 את \u0005שלך ואקח אני\u0006 את \u0005שלי]\u0006 ואשלם לך מה שאני חייב, ואקבל את הבגד ממך. \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב אחא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב אויא לרב אשי:\u0004 עדיין \u0003מצי אמר ליה\u0004 \u0005[יכול לומר לו]\u0006 האומן: \u0003לא צריכנא לשומא דידך\u0004 \u0005[איני צריך את האומדן שלך],\u0006 \u0003כבר שמוה קמאי דקמך\u0004 \u0005[אמדו\u0006 את הדבר \u0005ראשונים שלפניך]\u0006 ואיני זקוק לאומדן נוסף.","שנינו במשנה כי \u0003אריס\u0004 העובד בקרקע ומקבל אחוז מסויים מן היבול \u0003אין לו חזקה\u0004 באותה קרקע. ושואלים: \u0003אמאי\u0004 \u0005[מדוע]?\u0006 הרי \u0003עד האידנא פלגא\u0004 \u0005[עכשיו\u0006 היה מוחזק ל\u0005חצי]\u0006 שהוא נוטל מחצית הפירות בשכר עבודתו, \u0003והשתא\u0004 \u0005[ועכשיו]\u0006 את \u0003כולה.\u0004 ואם הוא מחזיק בכל, הרי הוא לוקח דבר שלא החזיק בו קודם, ומדוע יהא דינו שונה מכל אדם אחר? \u0003אמר ר' יוחנן:\u0004 מדובר במשנה \u0003באריסי בתי אבות,\u0004 שהאריסות נמשכת במשך דורות, ובסוג כזה של אריסות האריס מכניס את כל היבול לביתו, ומפריש ממנו את חלק בעל הבית, ואין ראיה מכך שהכניס לביתו את הכל.","\u0003אמר רב נחמן: אריס שהוריד אריסין\u0004 לשדה בעל הבית \u0003תחתיו\u0004 — \u0003יש לו חזקה\u0004 לשדה זו, \u0003מאי טעמא\u0004 \u0005[מה טעם\u0006 הדבר\u0005]?\u0006 \u0003דלא עביד אינש דנחתי אריסי לארעיה ושתיק\u0004 \u0005[שאין עשוי אדם שיירדו אריסים\u0006 זרים \u0005לאדמתו וישתוק],\u0006","ואם לא מחה בעל השדה ביד אריסו, משמע שהשדה שייך לאריס. \u0003אמר ר' יוחנן: אריס ש\u0004רק \u0003חלק\u0004 את הקרקע שהוא אריס עליה \u0003לאריסין\u0004 אחרים של אותם בעלים, \u0003אין לו חזקה\u0004 על ידי כך. \u0003מאי טעמא\u0004 \u0005[מה טעם\u0006 הדבר\u0005]?\u0006 — \u0003אימור הרמניא בעלמא שויוה\u0004 \u0005[אמור\u0006 שרק \u0005ממונה בלבד עשו אותו]\u0006 הבעלים, לחלק לאריסים האחרים, ואין זו הוכחה של בעלות על השדה.","\u0003שלח ליה\u0004 \u0005[לו]\u0006 \u0003רב נחמן בר רב חסדא לרב נחמן בר יעקב, ילמדנו רבינו:\u0004 אם בא אדם וערער על בעליו של שדה שהיה בו אריס, האם \u0003אריס\u0004 זה \u0003מעיד\u0004 לטובת הבעלים שיש להם זכות בשדה, \u0003או אינו מעיד\u0004 מפני שהוא נוגע בדבר? \u0003הוה יתיב\u0004 \u0005[היה יושב]\u0006 \u0003רב יוסף קמיה\u0004 \u0005[לפניו]\u0006 לפני רב נחמן, \u0003אמר ליה\u0004 \u0005[לו],\u0006 \u0003הכי\u0004 \u0005[כך]\u0006 \u0003אמר שמואל:\u0004 \u0003אריס מעיד.\u0004 והקשה לו: \u0003והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]\u0006 ש\u0003אינו מעיד!\u0004","ומשיבים, \u0003לא קשיא\u0004 \u0005[אין\u0006 זה \u0005קשה]:\u0006 \u0003הא דאיכא פירא בארעא\u0004 \u0005[זה שיש פירות בקרקע]\u0006 אינו כשר להעיד, מפני שהוא עתיד ליטול חלק בפירות, ואם יתברר שהשדה שייך לאחרים — יטלו ממנו את הפירות הללו. \u0003והא דליכא פירא בארעא\u0004 \u0005[וזה שאין פירות בקרקע]\u0006 שבמקרה זה אין האריס עומד להפסיד אם תעבור הקרקע לאחר, ומשום כך הוא נאמן להעיד לבעל השדה ככל אדם אחר.","ובענין זה מביאים הלכות דומות להלכות אלה \u0003(עמלק סימן)\u0004 (\u0003ע\u0004רב, \u0003מ\u0004לוה,\u0003ל\u0004קח, \u0003ק\u0004בלן).","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003ערב מעיד ללוה\u0004 לטובתו, אם אדם מערער על שדהו. ומעירים: \u0003והוא\u0004 דווקא באופן \u0003דאית ליה ארעא אחריתי\u0004 \u0005[\u0006כ\u0005שיש לו\u0006 ללווה \u0005קרקע אחרת],\u0006 שאפשר לגבות את כל חובו ממנה. שאם לא כן, יש לערב נגיעה בדבר, שאם לא יוכל המלווה לגבות מן הלווה — יצטרך הוא לשלם עבורו. וכיוצא בזה \u0003מלוה מעיד ללוה, והוא\u0004 דווקא באופן \u0003דאית ליה ארעא אחריתי\u0004 \u0005[שיש לו\u0006 ללווה \u0005קרקע אחרת].\u0006","וכיוצא בזה אם קנו שני אנשים קרקעות זה אחר זה מאדם אחד, ובא מערער על קרקעו של השני, הרי \u0003לוקח\u0004 (קונה) \u0003ראשון מעיד ללוקח שני\u0004 שהלוקח השני יושב בה כדין, \u0003והוא\u0004 דווקא באופן \u0003דאית ליה ארעא אחריתי\u0004 \u0005[שיש לו\u0006 ללוקח השני \u0005קרקע אחרת]\u0006 שקנה מאותו מוכר יחד עם קרקע זו, כך שאם תהא תביעה של בעל חוב קודם על המוכר יגבה ממנה, כדין קרקעות משועבדות, שגובה מן האחרונה שנמכרה, ולא יבוא לגבות מקרקעו של הקונה הראשון."],["ערב \u0003קבלן\u0004 שהמלוה יכול לגבות את חובו ממנו תחילה, \u0003אמרי לה\u0004 \u0005[יש אומרים]\u0006 שהוא \u0003מעיד\u0004 ללווה, \u0003ואמרי לה\u0004 \u0005[ו\u0006יש \u0005אומרים]\u0006 ש\u0003אינו מעיד. אמרי לה\u0004 \u0005[יש אומרים]\u0006 שהוא \u0003מעיד,\u0004 משום ש\u0003כערב דמי\u0004 \u0005[\u0006הוא \u0005נחשב],\u0006 ואם יש ללווה קרקע אחרת אינו נחשב עוד כנוגע בדבר. \u0003ואמרי לה\u0004 \u0005[ו\u0006יש \u0005אומרים]\u0006 ש\u0003אינו מעיד\u0004 ואף אם יש ללווה קרקע נוספת, משום \u0003דניחא ליה דלהוו בידיה תרוייהו\u0004 \u0005[שנוח לו שיהיו בידיו שניהם,\u0006 שני השדות\u0005],\u0006 \u0003דכי אתי\u0004 \u0005[שכאשר יבוא]\u0006 \u0003בעל חוב מאי דבעי שקיל\u0004 \u0005[מה שירצה יקח]\u0006 ולא יתבע כלל מן הערב\u0005.\u0006","\u0003אמר ר' יוחנן: אומן אין לו חזקה\u0004 כאשר נתבאר במשנה ובגמרא, אבל \u0003בן אומן\u0004 שאינו עוסק באותה אומנות \u0003יש לו חזקה.\u0004 וכן, אף ש\u0003אריס\u0004 עצמו \u0003אין לו חזקה, בן אריס יש לו חזקה.\u0004 לעומת זאת \u0003גזלן ובן גזלן אין להן חזקה,\u0004 אבל \u0003בן בנו של גזלן יש לו חזקה.\u0004","ומבררים: \u0003היכי דמי\u0004 \u0005[כיצד בדיוק מדובר]?\u0006 מדוע יש הבדל בין הבנים של כל אלה? \u0003אי אתו בטענתא דאבוהון\u0004 \u0005[אם\u0006 הם \u0005באים בטענה\u0006 שהדבר היה \u0005של אביהם],\u0006 \u0003אפילו הנך נמי\u0004 \u0005[אלה,\u0006 בן האומן ובן האריס, \u0005גם כן]\u0006 \u0003לא\u0004 תהא להם חזקה, שהרי הם באים בטענה מכוחו של מי שאין לו חזקה. \u0003אי\u0004 \u0005[אם]\u0006 ש\u0003לא אתו בטענתא דאבוהון\u0004 \u0005[באים\u0006 הם \u0005בטענה של אביהם]\u0006 אלא הם טוענים שהדבר שייך להם עצמם, \u0003אפילו בן גזלן נמי\u0004 \u0005[גם כן]\u0006 תהיה לו חזקה!","ומשיבים: \u0003לא צריכא\u0004 \u0005[נצרכה]\u0006 הלכה זו אלא למקרה \u0003דקא אמרי\u0004 \u0005[שאומרים]\u0006 \u0003עדים: \"בפנינו הודה לו\u0004 בעל החפץ לאביהם שהחפץ שייך לאב ושאינו גזול בידו \u0003\";\u0004 \u0003הנך איכא למימר קושטא קא אמרי\u0004 \u0005[אלה,\u0006 בן האומן ובן האריס, \u0005יש\u0006 מקום \u0005לומר\u0006 ש\u0005אמת\u0006 \u0005הם\u0006 \u0005אומרים],\u0006 שהרי היתה הודאה. \u0003האי אף על גב דאודי נמי לא מהימן\u0004 \u0005[זה,\u0006 בן הגזלן, \u0005אף על פי שהודה\u0006 הבעלים לאביו \u0005גם כן אינו נאמן],\u0006 \u0003כ\u0004דברי \u0003רב כהנא,\u0004 ש\u0003אמר רב כהנא: אי לאו דאודי ליה, הוה ממטי\u0004 \u0003ליה ולחמריה לשחוור\u0004 \u0005[אם לא שהיה מודה לו\u0006 שאינו גזול, \u0005היה מביא אותו ואת חמורו לפקיד\u0006 השלטון\u0005].\u0006","שכיון שהוא אדם אלים, היה גורם לתובע צרות הרבה, ולכן הודה לו באונס, ואין ממש בהודאה זו. והואיל ועל הודאה זו מסתמך בנו של הגזלן — אין לו חזקה. \u0003אמר רבא: פעמים שאפילו בן בנו של גזלן נמי\u0004 \u0005[גם כן]\u0006 \u0003אין לו חזקה. היכי דמי\u0004 \u0005[כיצד בדיוק מדובר]?\u0006 — \u0003כגון דקא אתי בטענתא דאבא דאבוה\u0004 \u0005[שהוא בא בטענה\u0006 שהנכסים האלה \u0005של אבי אביו],\u0006 שהרי הוא סומך על מי שאין לו חזקה.","ומבררים: \u0003היכי דמי\u0004 \u0005[כיצד בדיוק הוא]\u0006 \u0003גזלן\u0004 שאין לו חזקה? \u0003אמר ר' יוחנן: כגון שהוחזק על שדה זו בגזלנותא\u0004 \u0005[בגזלנות].\u0006 \u0003ורב חסדא אמר:\u0004 לא רק מי שידוע שגזל שדה מסויימת, אלא אף בסתם, \u0003כגון\u0004 אותם אנשים של \u0003בית פלוני\u0004 שהזכירו בשעתו את שמם ולא הזכירו אותם לדורות, \u0003שהורגין נפשות על עסקי ממון\u0004 והכל חוששים מהם, להם אין חזקה כלל בקרקע.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003אומן אין לו חזקה\u0004 על דברים שהוא מחזיק בהם כאומן, אבל אם \u0003ירד מאומנותו\u0004 ואינו עוסק בה עוד — \u0003יש לו\u0004 מאז \u0003חזקה\u0004 על מה שבידו. \u0003אריס אין לו חזקה\u0004 בקרקע שמעבד, ואם \u0003ירד מאריסותו\u0004 — \u0003יש לו חזקה\u0004 לאחר שלוש שנים. וכיוצא בזה, אף ששנינו במשנה שאין לבן חזקה בנכסי אביו, ולא לאשה חזקה בנכסי בעלה, מכל מקום \u0003בן שחלק\u0004 ואינו קשור עוד לעסקי ונכסי אביו, \u0003ואשה שנתגרשה\u0004 — \u0003הרי הן כשאר כל אדם\u0004 ויש להם חזקה לאחר שלוש שנים.","ומקשים: \u0003בשלמא\u0004 \u0005[נניח]\u0006 \u0003בן שחלק איצטריך\u0004 \u0005[נצרך]\u0006 הדבר להיאמר, כי \u0003סלקא דעתך אמינא\u0004 \u0005[יעלה על דעתך לומר]\u0006 שאין לו חזקה, שמא \u0003אחולי אחיל גביה\u0004 \u0005[מחל לו\u0006 האב\u0005]\u0006 ולא מחה בבנו, אבל אין הדבר שייך לבן, ואין לו חזקה, ועל כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 ש\u0003לא\u0004 חוששים לכך, וסומכים על החזקה. \u0003אלא אשה שנתגרשה פשיטא\u0004 \u0005[פשוט]\u0006 שיש לה חזקה, שהרי כבר אינה קשורה לבעלה, וצריך היה למחות! ומשיבים: \u0003לא צריכא\u0004 \u0005[נצרכה]\u0006 הלכה זו אלא"],["\u0003במגורשת ואינה מגורשת,\u0004 כלומר, אשה שיש ספק בגירושיה, \u0003וכ\u0004דברי \u0003ר' זירא,\u0004 ש\u0003אמר ר' זירא אמר ר' ירמיה בר אבא אמר שמואל: כל מקום שאמרו חכמים\u0004 באשה שמחמת ספק הריהי \u0003מגורשת ואינה מגורשת\u0004 — \u0003בעלה חייב במזונותיה\u0004 כל עוד לא נתגרשה גירושין גמורים. וכיון שכך, היה מקום לומר שיש לה זכות מסויימת בנכסיו, ואין להוכיח ממה שמחזיקה בהם, ולכן הוצרך לומר שאף אשה כזאת — יש לה חזקה, שאם היתה קרקע זו שלו — היה מוחה בה.","\u0003אמר רב נחמן, אמר לי\u0004 רב \u0003הונא: כולן,\u0004 כל אלה שנמנו לעיל, שאין להם חזקה, \u0003שהביאו ראיה\u0004 אם על ידי שטר או עדים — \u0003ראייתן ראיה, ומעמידין\u0004 את ה\u0003שדה בידן.\u0004 ואולם \u0003גזלן שהביא ראיה\u0004 — \u0003אין ראייתו ראיה, ואין מעמידין שדה בידו,\u0004 שחוששים שאף ראיה זו —","מחמת אונס נעשתה. ושואלים: \u0003מאי קא משמע לן\u0004 \u0005[מה השמיע לנו\u0006 בכך\u0005]?\u0006 הלא \u0003תנינא\u0004 \u0005[שנינו]\u0006 כבר דבר זה: \u0003לקח\u0004 (קנה) שדה \u0003מסיקריקון\u0004 (אנס) שגזל שדה זו, או גרם על ידי כפיה שהבעלים יוכרחו להעביר לו את השדה, \u0003וחזר ולקח\u0004 אחר כך את השדה \u0003מבעל הבית\u0004 — \u0003מקחו בטל.\u0004 משמע שאין משמעות למכירה שבאה בגזלנות, אף שיש ראיה למכירה!","ומשיבים: בכל זאת יש חידוש בדברי רב הונא, \u0003לאפוקי\u0004 \u0005[להוציא,\u0006 למעט\u0005]\u0006 \u0003מ\u0004דברי \u0003רב,\u0004 ש\u0003אמר רב:\u0004 \u0003לא שנו\u0004 שמקחו של הקונה מסיקריקון בטל, \u0003אלא\u0004 במקרה שרק \u0003אמר ליה\u0004 \u0005[לו]\u0006 הבעלים: \u0003\"לך חזק וקני\"\u0004 \u0005[החזק וקנה]\u0006 ולא כתב שטר, \u0003אבל\u0004 אם כתב לו ב\u0003שטר קנה.\u0004","\u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 רב הונא בדבריו שאין ראייתו של גזלן ראיה \u0003כ\u0004דברי \u0003שמואל\u0004 בענין סיקריקון, ש\u0003אמר: אף בשטר נמי\u0004 \u0005[גם כן]\u0006 \u0003לא קנה, עד שיכתוב\u0004 בעל הבית המוכר גם \u0003אחריות נכסים.\u0004","\u0003ורב ביבי מסיים בה\u0004 בהלכה זו של רב הונא, \u0003משמיה\u0004 \u0005[משמו]\u0006 של \u0003רב נחמן: קרקע אין לו\u0004 לגזלן, אף שיש בידו שטר קניה, \u0003אבל מעות\u0004 ששילם \u0003יש לו,\u0004 ומקבלם בחזרה מידי בעל השדה. \u0003במה דברים אמורים\u0004 שמקבל ממון בחזרה? — \u0003דווקא כ\u0004\u0003שאמרו עדים: בפנינו מנה לו\u0004 הגזלן כסף ושילם לו. \u0003אבל\u0004 אם \u0003אמרו עדים: בפנינו הודה לו\u0004 הבעלים ששילם לו — \u0003לא, כ\u0004דברי \u0003רב כהנא,\u0004 ש\u0003אמר: אי לאו דאודי ליה, הוה ממטי ליה לדידיה ולחמריה לשחוור\u0004 \u0005[אם לא שהיה מודה לו\u0006 בעל כורחו, \u0005היה מביא אותו ואת חמורו לפקיד\u0006 השלטון\u0005]\u0006 ולכן אין סומכים על הודאה בלבד.","ובענין זה של מכירה מתוך אונס \u0003אמר רב הונא:\u0004 אפילו \u0003תליוהו\u0004 \u0005[תלוהו,\u0006 את הבעלים\u0005]\u0006 או כפו אותו באופן אחר \u0003וזבין\u0004 \u0005[ומכר]\u0006 — \u0003זביניה זביני\u0004 \u0005[מכירתו מכירה].\u0006 ומבררים: \u0003מאי טעמא\u0004 \u0005[מה טעם\u0006 הדבר\u0005]?\u0006 אם משום ההנחה ש\u0003כל\u0004 מה \u0003דמזבין איניש\u0004 \u0005[שמוכר אדם]\u0006 מחפציו, \u0003אי לאו דאניס\u0004 \u0005[אם לא שאנוס]\u0006 היה מחמת חוסר כסף \u0003לא הוה מזבין\u0004 \u0005[היה מוכר],\u0006 \u0003ואפילו הכי זביניה זביני\u0004 \u0005[כך מכירתו מכירה],\u0006 ומשמע שלענין מכירה אין צורך שיהיה הדבר מרצונו השלם? — מכאן אין ראיה, \u0003ודילמא שאני אונסא דנפשיה מאונסא דאחריני\u0004 \u0005[ושמא שונה אונס של עצמו\u0006 כגון שזקוק לכסף \u0005מאונס ש\u0006נאנס על ידי \u0005אחרים]!\u0006 \u0003אלא\u0004 נאמר כי טעמו הוא \u0003כדתניא\u0004 \u0005[כפי ששנינו\u0006 בברייתא\u0005]:\u0006"],["נאמר לגבי קרבן עולה: \u0003\"\u0004יקריבנו... \u0003יקריב אתו\"\u0004 (ויקרא א, ג), וייתור הלשון \u0003מלמד שכופין אותו\u0004 להקריב, \u0003יכול\u0004 יקריב \u0003בעל כרחו\u0004 לגמרי? \u0003תלמוד לומר: \"לרצנו\"\u0004 (ויקרא א, ג)\u0003, הא\u0004 \u0005[הרי]\u0006 \u0003כיצד\u0004 אתה מיישב את הדברים? — \u0003כופין אותו עד שיאמר \"רוצה אני\".\u0004","משמע שאם כופים את האדם עד שהוא אומר \"רוצה אני\" הרי זה נחשב כעושה מרצונו, ואין צורך שיהא זה רצונו הפנימי, ומכאן רוצים ללמוד למכירה — גם אפשרות זו יש לדחות: \u0003ודלמא שאני התם\u0004 \u0005[ושמא שונה שם]\u0006 בענין קרבן, \u0003דניחא ליה דתיהוי ליה\u0004 \u0005[שנוח לו שתהיה לו]\u0006 \u0003כפרה\u0004 ומשום כך יש להניח שאכן רצונו בכך! \u0003ואלא\u0004 נאמר כי יש להביא הוכחה לדברי רב הונא \u0003מסיפא\u0004 \u0005[מ\u0006מה ששנינו ב\u0005סוף]\u0006 של אותה משנה: \u0003וכן אתה אומר בגיטי נשים,\u0004 שאם חייב אדם לתת גט \u0003כופין אותו\u0004 בבית דין \u0003עד שיאמר \"רוצה אני\",\u0004 ונחשב לו כאילו נתן מרצונו —","\u0003ודלמא שאני התם\u0004 \u0005[ו\u0006אולם \u0005שמא שונה שם],\u0006 שאנו מניחים שהוא מתכוון לעשות זאת משום ש\u0003מצוה לשמוע דברי חכמים,\u0004 ואם כן אין להביא משם ראיה לענין מקח וממכר סתמי. \u0003אלא\u0004 יש לומר כי דברי רב הונא \u0003סברא הוא\u0004 \u0005[סברה היא],\u0006 \u0003אגב אונסיה גמר\u0004 \u0005[מתוך אונסו\u0006 המוכר \u0005גומר\u0006 בדעתו\u0005]\u0006 \u0003ומקנה\u0004 קנין גמור.","\u0003מותיב\u0004 \u0005[מקשה]\u0006 על סברה זו \u0003רב יהודה\u0004 ממה ששנינו: \u0003גט המעושה,\u0004 כלומר, שהכריחו את הבעל לכותבו, אם כפו אותו \u0003ב\u0004בית דין של \u0003ישראל\u0004 שמן הדין צריך לגרש את אשתו — הרי זה \u0003כשר, ובגוים\u0004 — \u0003פסול, ו\u0004אם \u0003גוים חובטין אותו ואומרין לו:\u0004 \u0003עשה מה שישראל אומר לך\u0004 — הרי גם הוא כשר. \u0003ואמאי\u0004 \u0005[ומדוע]\u0006 יהא גט המעושה בגויים פסול? \u0003התם נמי נימא\u0004 \u0005[שם גם כן נאמר]:\u0006 \u0003אגב אונסיה גמר\u0004 \u0005[מתוך אונסו\u0006 הוא \u0005גומר\u0006 בליבו\u0005]\u0006 \u0003ומגרש!\u0004","ומשיבים: \u0003הא איתמר עלה\u0004 \u0005[הרי\u0006 באמת כבר \u0005נאמר עליה],\u0006 \u0003אמר רב משרשיא: דבר תורה,\u0004 כלומר, מעיקר הדין, ולפי התורה \u0003אפילו בגוים\u0004 הכופים אותו הגט \u0003כשר,\u0004 שכיון שאמר הבעל \"רוצה אני\" די בכך, \u0003ומה טעם אמרו\u0004 החכמים כי \u0003בגויים פסול?\u0004 — \u0003כדי שלא תהא כל אחת ואחת הולכת ותולה\u0004 את \u0003עצמה ביד גוי ומפקעת עצמה מיד בעלה\u0004 באופן זה שיכפה אותו הגוי לתת לה גט.","\u0003מותיב\u0004 \u0005[מקשה]\u0006 \u0003רב המנונא\u0004 ממה ששנינו במקום אחר: אם \u0003לקח\u0004 (קנה) יהודי שדה \u0003מסיקריקון\u0004 (אנס גוי) שהכריח את בעליו של השדה להעביר לו את השדה שלא מרצונו, \u0003וחזר ולקח\u0004 את השדה גם \u0003מבעל הבית\u0004 — \u0003מקחו בטל\u0004 לפי שהוא קונה שדה גזול. \u0003ואמאי\u0004 \u0005[ומדוע]?\u0006 \u0003התם נמי נימא\u0004 \u0005[שם גם כן נאמר]:\u0006 בעל השדה \u0003אגב אונסיה גמר ומקני\u0004 \u0005[מתוך אונסו גומר ומקנה]\u0006 אותו לאותו אדם, מפחד הסיקריקון!","ומשיבים: \u0003הא אתמר עלה\u0004 \u0005[הרי\u0006 כבר \u0005נאמר עליה],\u0006 \u0003אמר רב: לא שנו\u0004 שהמיקח בטל \u0003אלא\u0004 באופן ש\u0003אמר ליה\u0004 \u0005[לו]\u0006 בדיבור בלבד \u0003\"לך חזק וקני\"\u0004 \u0005[החזק וקנה],\u0006 \u0003אבל\u0004 אם כתב לו \u0003בשטר\u0004 — \u0003קנה.\u0004","ושואלים: \u0003ולשמואל\u0004 ש\u0003אמר: אף בשטר נמי\u0004 \u0005[גם כן]\u0006 \u0003לא קנה, מאי איכא למימר\u0004 \u0005[מה יש לומר]?\u0006 ומשיבים: \u0003מודה שמואל היכא דיהב זוזי\u0004 \u0005[במקום ש\u0006הוא \u0005נותן כסף].\u0006 שמה שאמרו שכתיבת שטר באונס אינה נחשבת, הרי זה כשמעביר מרכושו לאחר בלא לקבל תשלום.","אבל אם משלמים למוכר, אף על פי שהוא הסכים למכר רק מתוך אונס — הרי זה מכר. ושואלים: \u0003ולרב ביבי\u0004 שהיה \u0003מסיים בה\u0004 בהלכה שאמר רב הונא, לעיל, ששטר שביד גזלן אינו ראיה, \u0003משמיה\u0004 \u0005[משמו]\u0006 של \u0003רב נחמן: קרקע אין לו\u0004 לקונה שדה גזול, אבל \u0003מעות\u0004 ששילם עבור השדה \u0003יש לו,\u0004 ומחזיר לו המוכר, \u0003מאי איכא למימר\u0004 \u0005[מה יש לומר]?\u0006 שהרי משמע מדבריו שגם במקום שקיבל המוכר כסף (שהרי נאמר ש\"מעות יש לו\") גם אז אין מכר באונס, והקרקע אינה נקנית לקונה זה! ומשיבים: מה שאמר \u0003רב ביבי מימרא\u0004 \u0005[אימרה]\u0006 של אמוראים \u0003הוא, ומימרא\u0004 \u0005[ואימרה]\u0006 זו \u0003רב הונא לא סבירא ליה\u0004 \u0005[איננו סובר אותה].\u0006","\u0003אמר רבא\u0004 בסיכום: \u0003הלכתא\u0004 \u0005[הלכה\u0006 היא\u0005]:\u0006 \u0003תליוהו וזבין\u0004 \u0005[תלוהו ומכר]\u0006 — \u0003זביניה זביני\u0004 \u0005[\u0006\u0005מכירתו מכר].\u0006 \u0003ולא אמרן\u0004 \u0005[אמרנו]\u0006 דבר זה \u0003אלא\u0004"],["\u0003ב\u0004מקרה שהכריחוהו למכור \u0003שדה סתם,\u0004 והוא החליט מדעת עצמו למכור שדה מסויים, שבאופן זה יש להניח שגמר בדעתו לקיים את המכירה. \u0003אבל ב\u0004מקרה שהכריחוהו למכור \u0003\"שדה זו\"\u0004 — \u0003לא,\u0004 שאונס היה, שלא היתה מעורבת בכך כלל החלטה שלו.","\u0003וב\"שדה זו\" נמי\u0004 \u0005[גם כן]\u0006 \u0003לא אמרן\u0004 \u0005[אמרנו]\u0006 שאין זה מכר, \u0003אלא\u0004 באופן ש\u0003לא ארצי זוזי\u0004 \u0005[נתן לידו כסף\u0006 ממש\u0005],\u0006 \u0003אבל ארצי זוזי\u0004 \u0005[נתן לידו כסף]\u0006 — \u0003לא,\u0004 והמכר קיים.","\u0003ולא אמרן\u0004 \u0005[אמרנו]\u0006 שהמכר בטל ב\"שדה זו\" \u0003אלא\u0004 במקום ש\u0003לא הוה לאישתמוטי\u0004 \u0005[היתה לו\u0006 למוכר אפשרות \u0005להשתמט]\u0006 מן המכירה. \u0003אבל\u0004 אם \u0003הוה ליה לאישתמוטי\u0004 \u0005[היתה לו\u0006 אפשרות \u0005להשתמט]\u0006 ולא עשה כן — \u0003לא,\u0004 והמכר קיים.","ומסכמים: \u0003והלכתא בכולהו\u0004 \u0005[והלכה בכולם]\u0006 בכל האופנים \u0003דהוו זביניה זביני\u0004 \u0005[שמכירתו מכירה],\u0006 \u0003ואפילו ב\"שדה זו\", דהא\u0004 \u0005[שהרי]\u0006 \u0003אשה\u0004 שאדם מקדש \u0003כ\"שדה זו\" דמיא\u0004 \u0005[\u0006היא \u0005נחשבת],\u0006 \u0003ו\u0004בכל זאת \u0003אמר אמימר: תליוה וקדיש\u0004 \u0005[מי שתלו,\u0006 כפו \u0005אותו, וקידש\u0006 אשה\u0005]\u0006 (רמב\"ם) — \u0003קדושיו קדושין.\u0004","\u0003מר בר רב אשי אמר: באשה\u0004 שקידש אותה אדם שלא מרצונה, \u0003ודאי קדושין לא הוו\u0004 \u0005[אין הם\u0006 חלים\u0005],\u0006 ומדוע? — כיון ש\u0003הוא עשה שלא כהוגן\u0004 והכריחה באונס להתקדש לו, \u0003לפיכך\u0004 חכמים \u0003עשו עמו שלא כהוגן\u0004 (שלא לפי עיקר הדין) \u0003ואפקעינהו רבנן לקידושיה מיניה\u0004 \u0005[והפקיעו חכמים את קידושיה ממנו].\u0006","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבינא לרב אשי:\u0004 כיצד יכולים חכמים להפקיע קידושין? \u0003תינח דקדיש בכספא\u0004 \u0005[נניח\u0006 במקרה \u0005שמקדש בכסף]\u0006 אפשר לומר שחכמים החרימו, הפקירו את הכסף הזה, וכאילו לא קידש כלל. אבל אם \u0003קדיש\u0004 \u0005[מקדש]\u0006 \u0003בביאה, מאי איכא למימר\u0004 \u0005[מה יש לומר]?\u0006 כיצד יכולים חכמים לבטל את המעשה הזה? \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003שויוה רבנן\u0004 \u0005[עשו חכמים]\u0006 את \u0003בעילתו\u0004 כ\u0003בעילת זנות,\u0004 ובעילת זנות אינה קונה לקידושין.","מסופר: איש אחד ששמו \u0003טאבי תלא\u0004 \u0005[תלה]\u0006 איש אחר שנקרא \u0003פאפי אכינרא וזבין\u0004 \u0005[על\u0006 עץ \u0005כינר ומכר\u0006 לו\u0005]\u0006 שדה, \u0003חתם רבה בר בר חנה\u0004 גם \u0003אמודעא\u0004 \u0005[על המודעה]\u0006 שכתב פאפי שהוא מוכר באונס, \u0003ו\u0004גם \u0003אאשקלתא\u0004 \u0005[על שטר מכר]\u0006 של אותו שדה לטאבי. \u0003אמר רב הונא: מאן דחתים אמודעא\u0004 \u0005[מי שחתם על המודעה]\u0006 — \u0003שפיר חתים\u0004 [\u0005יפה חתם],\u0006 \u0003ומאן דחתים אאשקלתא\u0004 \u0005[ומי שחתם על שטר המכר]\u0006 — \u0003שפיר חתים\u0004 [\u0005יפה חתם].\u0006","על דברים אלה תוהים: \u0003מה נפשך\u0004 \u0005[רצונך]\u0006 לומר? \u0003אי מודעא\u0004 \u0005[אם מודעה]\u0006 זו יש לה תוקף — \u0003לא אשקלתא\u0004 \u0005[אין\u0006 כאן \u0005שטר מכר],\u0006 \u0003ואי אשקלתא לא מודעא\u0004 \u0005[ואם\u0006 קיים \u0005שטר מכר אין\u0006 משמעות ל\u0005מודעה]\u0006 וכיצד אפשר לומר ששניהם טובים? ומשיבים: \u0003הכי קאמר\u0004 \u0005[כך אמר]:\u0006 \u0003אי לאו מודעא, מאן דחתים אאשקלתא\u0004 \u0005[אם לא\u0006 היתה \u0005מודעה\u0006 קודם, \u0005מי שחתם על שטר המכר]\u0006 — \u0003שפיר חתים\u0004 \u0005[יפה חתם],\u0006 שמכירה זו יש לה תוקף. ו\u0003רב הונא\u0004 הולך בענין זה \u0003לטעמיה\u0004 \u0005[לטעמו\u0006 לשיטתו\u0005],\u0006 ש\u0003אמר רב הונא: תליוהו וזבין\u0004 — \u0003זביניה זביני\u0004 \u0005[תלוהו ומכר\u0006 — \u0005מכירתו מכירה].\u0006","ומקשים: \u0003איני\u0004 \u0005[כן הוא]?\u0006 שיכול העד החותם על השטר להעיד (על ידי המודעה) ששטר זה אינו אמיתי? \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003רב נחמן: העדים שאמרו \"אמנה היו דברינו\"\u0004 כלומר, אמת שחתמנו על השטר, אבל יודעים אנו ששטר זה היה שטר אמנה בלבד. ועניינו, שלא היתה שם הלוואה ממש, אלא הסכימו הצדדים לכותבו מראש, ולהשתמש בו משעה שתיעשה ההלוואה בפועל —"],["\u0003אין נאמנים\u0004 על אמירה זו, שאינם יכולים בעדותם לבטל תוקפו של שטר שהם עצמם מודים שנכתב ונחתם על ידם. וכן אם אומרים העדים על שטר מכר שחתמו עליו: \u0003\"מודעא היו דברינו\",\u0004 כלומר, נמסרה בפנינו מודעה שמכר זה נעשה באונס — \u0003אין נאמנין.\u0004 ואם כן, כיצד אנו אומרים כאן ששטר המודעה מבטל את תוקפו של שטר הקנין שנכתב ונחתם על ידם כדין?","ומתרצים: \u0003הני מילי\u0004 \u0005[דברים אלה],\u0006 שאין העדים נאמנים, אמורים כאשר העדים אומרים זאת בעדות \u0003על פה,\u0004 ש\u0003לא אתי\u0004 \u0005[באה]\u0006 עדות שב\u0003על פה ומרעא לשטרא\u0004 \u0005[ומריעה את\u0006 כוחו של \u0005שטר]\u0006 כתוב, \u0003אבל\u0004 אם היתה המודעה \u0003בשטרא\u0004 \u0005[בשטר]\u0006 — \u0003אתי שטרא ומרעא לשטרא\u0004 \u0005[בא שטר\u0006 המודעה \u0005ומרע את\u0006 כוחו של \u0005השטר\u0006 האחר\u0005].\u0006","כיון שהזכרנו הלכה זו דנים בה \u0003גופא\u0004 \u0005[לגופה],\u0006 \u0003אמר רב נחמן:\u0004 אם אמרו עדים החתומים על השטר \u0003\"אמנה היו דברינו\"\u0004 — \u0003אין נאמנין,\u0004 ואם אמרו \u0003\"מודעא היו דברינו\"\u0004 — \u0003אין נאמנין;\u0004","\u0003ומר בר רב אשי אמר:\u0004 אם אמרו \u0003\"אמנה היו דברינו\"\u0004 — \u0003אין נאמנין,\u0004 אבל אם אמרו \u0003\"מודעא היו דברינו\"\u0004 — \u0003נאמנין, מאי טעמא\u0004 \u0005[מה טעם\u0006 הדבר\u0005]?\u0006 — \u0003שזה\u0004 שטר מודעה \u0003ניתן ליכתב,\u0004 שאפשר ומותר לכתוב אותו, על מנת לבטל מכירה הנעשית באונס, אבל \u0003זה\u0004 שטר אמנה \u0003לא ניתן ליכתב\u0004 כלל, כי עצם כתיבתו של שטר כזה הוא מעשה עוולה, היכול להזיק לאחרים, ואסור לכותבו, וכל הכותבו כאילו מעיד על עצמו שרשע הוא, ואין עדותו מתקבלת.","שנינו ש\u0003לא לאיש חזקה בנכסי אשתו וכו'.\u0004 ותוהים: \u0003פשיטא\u0004 \u0005[פשוט,\u0006 מובן מאליו\u0005],\u0006 \u0003כיון דאית ליה לפירא\u0004 \u0005[שיש לו\u0006 זכות לאכול \u0005את פירות\u0006 נכסיה\u0005]\u0006 כשהיא נשואה לו, יודעים כולם כי רק \u0003פירא\u0004 \u0005[פירות]\u0006 \u0003הוא דקאכיל\u0004 \u0005[שאוכל]\u0006 אבל אין לו זכות בגוף השדה, ומה חזקה הוא קונה על ידי אכילת הפירות?","ומשיבים: \u0003לא צריכא\u0004 \u0005[נצרכה]\u0006 הלכה זו אלא אף במקרה \u0003דכתב\u0004 \u0005[שכותב]\u0006 \u0003לה\u0004 הבעל לאשתו: \u0003דין ודברים אין לי בנכסייך\u0004, שמוותר הוא על זכות ההנאה מפירות נכסיה, ולכן ניתן היה לחשוב שאם נכנס אחר כך לנכסיה ואכל מהם — שמא זו הוכחה שקנה ממנה אותם. ולכן נצרכה המשנה לומר שאין מכך הוכחה, שיש לומר כי מפני יחסי הנישואין לא מחתה בו על שאכל את הפירות.","ושואלים: \u0003וכי כתב לה מאי הוי\u0004 \u0005[וכאשר כותב לה\u0006 לשון זו \u0005מה בכך]?\u0006 \u0003והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005],\u0006 \u0003האומר לחבירו: \"דין ודברים אין לי על שדה זו\", ו\u0004כן אם אומר \u0003\"אין לי עסק בה\", ו\u0004כיוצא בזה אם אומר \u0003\"ידי מסולקות ממנה\"\u0004 — \u0003לא אמר כלום,\u0004 שאין אמירה בלשון זו מחייבת מבחינת ההלכה, ואם יש לו זכויות או תביעות, לא בטלו על ידי כך. ונמצא שאף במקרה זה אין שום חידוש בדין משנתנו!","\u0003אמרי לה דבי\u0004 \u0005[אומרים אותה\u0006 החכמים \u0005מבית\u0006 מדרשו\u0005]\u0006 של \u0003ר' ינאי: מתניתין\u0004 \u0005[משנתנו]\u0006 עוסקת במקרה בו יועיל נוסח זה, והוא \u0003בכותב לה\u0004 לאשתו נוסח זה \u0003ועודה ארוסה,\u0004 לפני שהיתה לו זכות קנין בנכסיה. \u0003וכ\u0004דברי \u0003רב כהנא,\u0004 ש\u0003אמר רב כהנא:\u0004"],["\u0003נחלה\u0004 (ירושה) \u0003הבאה לו לאדם ממקום אחר,\u0004 כלומר, נחלה שעתידה לבוא לו ועדיין לא הגיעה לו בפועל, \u0003אדם מתנה עליה\u0004 לפני כן \u0003שלא יירשנה,\u0004 שיכול אדם לסלק עצמו מזכות שתבוא לו בעתיד, כל עוד אינה רכושו כעת. \u0003וכ\u0004דברי \u0003רבא,\u0004 ש\u0003אמר רבא: כל האומר \"אי אפשי\u0004 (אין רצוני) \u0003בתקנת חכמים\u0004 שתיקנו לטובתי \u0003כגון זאת\"\u0004 — \u0003שומעין לו.\u0004","ושואלים: \u0003מאי\u0004 \u0005[מה]\u0006 פירוש \u0003\"כגון זאת\"?\u0004 לאיזו תקנה הוא מתכוון? ומסבירים: \u0003כ\u0004דברי \u0003רב הונא אמר רב,\u0004 ש\u0003אמר רב הונא אמר רב: יכולה אשה שתאמר לבעלה \"איני ניזונת\u0004 מנכסיך \u0003ואיני עושה\u0004 מלאכה עבורך\", שתקנת חכמים — שתהא האשה ניזונת מנכסי בעלה, ותמורת זה היא עושה מלאכה — נעשתה לטובתה של האשה, ויכולה האשה לומר שאינה רוצה בתקנה כזו. וכן בכל דבר שתיקנו חכמים לטובתו של אדם, כגון זכותו של הבעל לפירות של נכסי האשה — יכול הוא לומר שאינו רוצה בתקנת חכמים זו. ועל כך אמרה משנתנו, שאף במקרה כזה — לא תהא חזקה לבעל שאכל מפירות נכסי אשתו.","שואלים: שנינו שאין לבעל חזקה בנכסי אשתו, שעצם העובדה שהשתמש בהם אינה ראיה לבעלות, ומכאן יש להבין כי \u0003הא\u0004 \u0005[הרי]\u0006 באמצעות \u0003ראיה\u0004 של עדים או שטר שהאשה נתנה או מכרה לו את הנכסים \u0003יש\u0004 לבעל זכות בנכסים. ויש לשאול: מדוע תועיל ראיה זו? \u0003תימא\u0004 \u0005[תאמר]\u0006 האשה: \u0003\"נחת רוח עשיתי לבעלי\",\u0004 שמכרה או שנתנה לו את הנכס, אבל באמת לא התכוונה לכך בלב שלם, אלא עשתה לפי שעה, כדי שלא תהיה מריבה ביניהם.","\u0003מי\u0004 \u0005[האם]\u0006 \u0003לא תנן\u0004 \u0005[שנינו\u0006 במשנה\u0005]:\u0006 אם \u0003לקח\u0004 (קנה) שדה \u0003מן האיש, וחזר ולקח\u0004 אותו שדה \u0003מן האשה,\u0004 כלומר, את זכותה לגבות כתובתה משדה זה לאחר מות הבעל, או לאחר גירושין — אף על פי כן \u0003מקחו בטל, אלמא אמרה\u0004 \u0005[מכאן\u0006 יוצא שהאשה יכולה \u0005לומר]:\u0006 \u0003\"נחת רוח עשיתי לבעלי\"\u0004 שחתמתי על שטר המכר כדי שיוכל למכור את השדה, ובאמת לא התכוונתי לכך. \u0003הכא נמי תימא\u0004 \u0005[כאן גם כן תאמר]:\u0006 \u0003\"נחת רוח עשיתי לבעלי\u0004 שמכרתי או נתתי לו את השדה\"!","ומשיבים: \u0003הא איתמר עלה\u0004 \u0005[הרי נאמר עליה],\u0006 \u0003אמר רבה בר רב הונא: לא נצרכה\u0004 הלכה זו שיכולה האשה לטעון \"נחת רוח עשיתי\", \u0003אלא באותן שלש שדות,\u0004 שבהן יש דין מיוחד זה: \u0003אחת\u0004 שדה \u0003שכתב לה בכתובתה\u0004 שפירש בכתובה שמשדה זה תגבה את הכתובה,"]]};
